// getValue returns the value of an optional string pointer, or empty string if nil
func getValue(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

// stringPtr returns a pointer to a string, or nil if the string is empty
func stringPtr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// addMoney adds two Money values in int64 space to avoid floating point precision errors.
// It converts both to total nanos (units * 1e9 + nanos), adds them, then converts back.
func addMoney(a, b *money.Money) *money.Money {
	if a == nil && b == nil {
		return nil
	}
	if a == nil {
		return &money.Money{CurrencyCode: b.CurrencyCode, Units: b.Units, Nanos: b.Nanos}
	}
	if b == nil {
		return &money.Money{CurrencyCode: a.CurrencyCode, Units: a.Units, Nanos: a.Nanos}
	}

	// Convert to total nanos (int64 arithmetic only)
	aTotalNanos := a.Units*1e9 + int64(a.Nanos)
	bTotalNanos := b.Units*1e9 + int64(b.Nanos)
	totalNanos := aTotalNanos + bTotalNanos

	// Split back into units and nanos
	units := totalNanos / 1e9
	nanos := totalNanos % 1e9

	return &money.Money{
		CurrencyCode: a.CurrencyCode,
		Units:        units,
		Nanos:        int32(nanos),
	}
}

// parseStringToMoney parses a decimal string directly into Money to avoid float precision errors.
// For example, "45.980701" becomes {Units: 45, Nanos: 980701000} without float rounding.
func parseStringToMoney(s string, currency string) (*money.Money, error) {
	if s == "" || s == "0" {
		return &money.Money{CurrencyCode: currency, Units: 0, Nanos: 0}, nil
	}

	// Handle negative values
	negative := false
	if strings.HasPrefix(s, "-") {
		negative = true
		s = s[1:]
	}

	// Split on decimal point
	parts := strings.Split(s, ".")

	// Parse units (whole dollar part)
	units := int64(0)
	if len(parts) > 0 && parts[0] != "" {
		parsed, err := strconv.ParseInt(parts[0], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("failed to parse units from '%s': %w", s, err)
		}
		units = parsed
	}

	// Parse nanos (fractional part)
	nanos := int32(0)
	if len(parts) > 1 {
		// Pad or truncate to exactly 9 digits
		fractional := parts[1]
		if len(fractional) > 9 {
			fractional = fractional[:9] // Truncate
		} else {
			fractional = fractional + strings.Repeat("0", 9-len(fractional)) // Pad with zeros
		}
		parsed, err := strconv.ParseInt(fractional, 10, 32)
		if err != nil {
			return nil, fmt.Errorf("failed to parse nanos from '%s': %w", s, err)
		}
		nanos = int32(parsed)
	}

	// Apply negative sign
	if negative {
		units = -units
		nanos = -nanos
	}

	return &money.Money{
		CurrencyCode: currency,
		Units:        units,
		Nanos:        nanos,
	}, nil
}

// Orb API response structures
type OrbSubscriptionCostsResponse struct {
	Data []OrbCostData `json:"data"`
}

type OrbCostData struct {
	Total          string         `json:"total"`
	PerPriceCosts  []OrbPriceCost `json:"per_price_costs"`
	TimeframeStart time.Time      `json:"timeframe_start"`
	TimeframeEnd   time.Time      `json:"timeframe_end"`
}

type OrbPriceCost struct {
	Price       OrbPrice        `json:"price"`
	Total       string          `json:"total"`
	Quantity    float64         `json:"quantity"`
	PriceGroups []OrbPriceGroup `json:"price_groups"`
}

type OrbPrice struct {
	Name         string           `json:"name"`
	Currency     string           `json:"currency"`
	MatrixConfig *OrbMatrixConfig `json:"matrix_config"`
	UnitConfig   *OrbUnitConfig   `json:"unit_config"`
}

type OrbMatrixConfig struct {
	MatrixValues []OrbMatrixValue `json:"matrix_values"`
}

type OrbMatrixValue struct {
	DimensionValues []string `json:"dimension_values"`
	UnitAmount      string   `json:"unit_amount"`
}

type OrbUnitConfig struct {
	UnitAmount string `json:"unit_amount"`
}

type OrbPriceGroup struct {
	GroupingKey            string  `json:"grouping_key"`
	GroupingValue          string  `json:"grouping_value"`
	Quantity               float64 `json:"quantity"`
	SecondaryGroupingKey   string  `json:"secondary_grouping_key"`
	SecondaryGroupingValue string  `json:"secondary_grouping_value"`
	Total                  string  `json:"total"`
}

// GetBillingSummary retrieves billing summary information for an account
// It accepts account_id, start_time, and end

_time parameters and returns detailed billing breakdown
func (s *Server) GetBillingSummary(ctx context.Context, req *gpb.GetBillingSummaryRequest) (*gpb.GetBillingSummaryResponse, error) {
	// Validate request using protovalidate
	if err := protovalidate.Validate(req); err != nil {
		return nil, fwerror.New(gpb.Code_INVALID_ARGUMENT, "validation failed: %w", err)
	}

	// Parse the account resource name to extract account ID
	var accountName resourcename.AccountName
	err := accountName.ParseFrom(req.Name)
	if err != nil {
		return nil, fwerror.New(gpb.Code_INVALID_ARGUMENT, "invalid account resource name '%s'. Please provide a valid resource name in the format 'accounts/account-id'. Error: %w", req.Name, err)
	}

	accountID := accountName.AccountId

	// Create logger with account context
	l := log.Ctx(ctx).With().Str("account_id", accountID).Logger()

	startTime := req.StartTime.AsTime()
	endTime := req.EndTime.AsTime()

	// Authentication and authorization are handled by interceptors

	// Look up the account to get billing information including Orb subscription ID
	var dba database.Account
	err = dba.Populate(s.DB(ctx), &accountName)
	if err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fwerror.New(gpb.Code_PERMISSION_DENIED, "")
		}
		return nil, fmt.Errorf("error getting account: %w", err)
	}

	// Hide cost breakdown details for accounts that have chosen to restrict detailed usage information.
	p := auth.GetPrincipalFromCtx(ctx)
	if s.hidesUsageDetail(p, dba.AccountId) {
		return &gpb.GetBillingSummaryResponse{LineItems: []*gpb.LineItem{}}, nil
	}

	// Serve from cache, keyed by account + Orb subscription + day-truncated range +
	// granularity. dba is loaded above to gate existence/auth and to supply the
	// subscription id: keying on it means an account that had no subscription (and
	// so cached an empty summary) gets a fresh key the moment one is synced, rather
	// than serving the stale empty result until expiry.
	key := billingSummaryCacheKey{
		AccountID:      accountID,
		SubscriptionID: dba.OrbSubscriptionId,
		StartDate:      startTime.UTC().Format(billingSummaryDateLayout),
		EndDate:        endTime.UTC().Format(billingSummaryDateLayout),
		Granularity:    req.GetGranularity(),
	}
	if s.billingSummaryCache == nil {
		return s.fetchBillingSummary(ctx, key)
	}
	response, cacheHit, err := s.billingSummaryCache.GetWithFound(ctx, key)
	if err != nil {
		return nil, err
	}
	l.Info().
		Bool("cache_hit", cacheHit).
		Int("line_items_count", len(response.GetLineItems())).
		Msg("GetBillingSummary: served billing summary")
	return response, nil
}

const billingSummaryDateLayout = "2006-01-02"

type billingSummaryCacheKey struct {
	AccountID      string
	SubscriptionID string
	StartDate      string
	EndDate        string
	Granularity    gpb.GetBillingSummaryRequest_Granularity
}

// fetchBillingSummary loads cost data from Orb and builds the response for a key.
func (s *Server) fetchBillingSummary(ctx context.Context, key billingSummaryCacheKey) (*gpb.GetBillingSummaryResponse, error) {
	response := &gpb.GetBillingSummaryResponse{
		LineItems: []*gpb.LineItem{},
	}
	if key.Granularity == gpb.GetBillingSummaryRequest_DAILY {
		response.UsageBuckets = []*gpb.UsageBucket{}
	}

	if key.SubscriptionID == "" {
		log.Ctx(ctx).Info().
			Str("account_id", key.AccountID).
			Msg("GetBillingSummary: no Orb subscription ID, returning empty summary")
		return response, nil
	}

	startTime, err := time.Parse(billingSummaryDateLayout, key.StartDate)
	if err != nil {
		return nil, fmt.Errorf("invalid start date %q: %w", key.StartDate, err)
	}
	endTime, err := time.Parse(billingSummaryDateLayout, key.EndDate)
	if err != nil {
		return nil, fmt.Errorf("invalid end date %q: %w", key.EndDate, err)
	}

	costData, err := s.fetchOrbCostData(ctx, key.SubscriptionID, startTime, endTime)
	if err != nil {
		return nil, fmt.Errorf("billing data is temporarily unavailable. The billing service may be experiencing issues. Please try again later or contact support if the problem persists. Error: %w", err)
	}

	buckets, err := s.buildUsageBuckets(costData)
	if err != nil {
		return nil, fmt.Errorf("error building usage buckets: %w", err)
	}
	response.LineItems = mergeLineItems(ctx, buckets)

	if key.Granularity == gpb.GetBillingSummaryRequest_DAILY {
		response.UsageBuckets = buckets
	}

	return response, nil
}

// fetchOrbCostData fetches per-day cost data from Orb for a subscription.
// TODO: Move to the Orb client library instead.
func (s *Server) fetchOrbCostData(ctx context.Context, subscriptionID string, startTime, endTime time.Time) ([]OrbCostData, error) {
	l := log.Ctx(ctx)

	// Get Orb API configuration from server config
	orbApiBase := "https://api.withorb.com/v1"
	orbApiKey := s.orbAPIKey

	// Format times as ISO 8601 with timezone
	start := startTime.Format("2006-01-02T15:04:05Z")
	end := endTime.Format("2006-01-02T15:04:05Z")

	// Build URL using url.JoinPath for proper URL construction
	apiURL, err

 := url.JoinPath(orbApiBase, "subscriptions", subscriptionID, "costs")
	if err != nil {
		return nil, fmt.Errorf("failed to construct Orb API URL: %w", err)
	}

	// Create HTTP request
	req, err := http.NewRequestWithContext(ctx, "GET", apiURL, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to create HTTP request to Orb API, this is likely a configuration issue, please contact support: %w", err)
	}

	// Add query parameters
	q := req.URL.Query()
	q.Add("timeframe_start", start)
	q.Add("timeframe_end", end)
	q.Add("view_mode", "periodic")
	req.URL.RawQuery = q.Encode()

	// Add headers
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", orbApiKey))

	l.Info().
		Str("subscription_id", subscriptionID).
		Str("url", apiURL).
		Str("start_time", start).
		Str("end_time", end).
		Msg("Making direct HTTP call to Orb API")

	// Make the HTTP request
	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("HTTP request to Orb API failed, this could indicate network connectivity issues or Orb service being temporarily unavailable, please try again later or contact support: %w", err)
	}
	defer resp.Body.Close()

	// Check status code
	if resp.StatusCode != 200 {
		body, _ := io.ReadAll(resp.Body)
		return nil, fmt.Errorf("orb API request failed with status %d, this could indicate: (1) invalid subscription ID '%s', (2) invalid time range, (3) Orb service temporarily unavailable, or (4) authentication issues, response: %s", resp.StatusCode, subscriptionID, string(body))
	}

	// Read response body
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("failed to read response body from Orb API, this could indicate a network issue or corrupted response, please try again: %w", err)
	}

	// Parse JSON response
	var orbResponse OrbSubscriptionCostsResponse
	if err := json.Unmarshal(body, &orbResponse); err != nil {
		return nil, fmt.Errorf("failed to parse JSON response from Orb API, the response format may have changed or the response is corrupted, response body: %s: %w", string(body), err)
	}

	return orbResponse.Data, nil
}

// mergeLineItems folds per-day usage buckets into range-level line items,
// merging rows that share the same category and grouping fields. It operates
// purely on already-built line items, so it does not depend on OrbCostData.
func mergeLineItems(ctx context.Context, buckets []*gpb.UsageBucket) []*gpb.LineItem {
	// Aggregate across buckets by category and grouping fields
	// (everything except unitAmount, currency, quantity, and totalCost).
	type aggregationKey struct {
		category               string
		groupingKey            string
		groupingValue          string
		secondaryGroupingKey   string
		secondaryGroupingValue string
	}

	aggregated := make(map[aggregationKey]*gpb.LineItem)

	for _, bucket := range buckets {
		for _, item := range bucket.GetLineItems() {
			key := aggregationKey{
				category:               getValue(item.Category),
				groupingKey:            getValue(item.GroupingKey),
				groupingValue:          getValue(item.GroupingValue),
				secondaryGroupingKey:   getValue(item.SecondaryGroupingKey),
				secondaryGroupingValue: getValue(item.SecondaryGroupingValue),
			}

			// Aggregate or update existing line item if key already exists
			if existing, exists := aggregated[key]; exists {
				if existing.UnitAmount != nil && item.UnitAmount != nil {
					existingUnitAmount := float64(existing.UnitAmount.Units) + float64(existing.UnitAmount.Nanos)/1e9
					itemUnitAmount := float64(item.UnitAmount.Units) + float64(item.UnitAmount.Nanos)/1e9

					if existingUnitAmount != itemUnitAmount || existing.UnitAmount.CurrencyCode != item.UnitAmount.CurrencyCode {
						log.Ctx(ctx).Warn().
							Str("category", getValue(item.Category)).
							Str("grouping_value", getValue(item.GroupingValue)).
							Msg("billing summary: unit_amount/currency varied; clearing unit amount")
						existing.UnitAmount = nil
					}
				}

				existing.Quantity += item.Quantity
				existing.TotalCost = addMoney(existing.TotalCost, item.TotalCost)
			} else {
				// Add new line item (deep copy to avoid reference issues)
				newItem := &gpb.LineItem{
					Category:               item.Category,
					GroupingKey:            item.GroupingKey,
					GroupingValue:          item.GroupingValue,
					SecondaryGroupingKey:   item.SecondaryGroupingKey,
					SecondaryGroupingValue: item.SecondaryGroupingValue,
					Quantity:               item.Quantity,
					TotalCost: &money.Money{
						CurrencyCode: item.TotalCost.CurrencyCode,
						Units:        item.TotalCost.Units,
						Nanos:        item.TotalCost.Nanos,
					},
				}
				// Copy unit amount if present
				if item.UnitAmount != nil {
					newItem.UnitAmount = &money.Money{
						CurrencyCode: item.UnitAmount.CurrencyCode,
						Units:        item.UnitAmount.Units,
						Nanos:        item.UnitAmount.Nanos,
					}

			}
				aggregated[key] = newItem
			}
		}
	}

	// Convert map to slice
	result := make([]*gpb.LineItem, 0, len(aggregated))
	for _, item := range aggregated {
		result = append(result, item)
	}

	// Sort by category, then grouping value, then secondary grouping value
	sort.Slice(result, func(i, j int) bool {
		if getValue(result[i].Category) != getValue(result[j].Category) {
			return getValue(result[i].Category) < getValue(result[j].Category)
		}
		if getValue(result[i].GroupingValue) != getValue(result[j].GroupingValue) {
			return getValue(result[i].GroupingValue) < getValue(result[j].GroupingValue)
		}
		return getValue(result[i].SecondaryGroupingValue) < getValue(result[j].SecondaryGroupingValue)
	})

	return result
}

// buildUsageBuckets returns one bucket of line items per day.
func (s *Server) buildUsageBuckets(data []OrbCostData) ([]*gpb.UsageBucket, error) {
	usageBuckets := make([]*gpb.UsageBucket, 0, len(data))
	for _, dataPoint := range data {
		lineItems, err := s.formatLineItems(&dataPoint)
		if err != nil {
			return nil, err
		}
		usageBuckets = append(usageBuckets, &gpb.UsageBucket{
			StartTime: timestamppb.New(dataPoint.TimeframeStart),
			EndTime:   timestamppb.New(dataPoint.TimeframeEnd),
			LineItems: lineItems,
		})
	}
	return usageBuckets, nil
}

// formatLineItems converts Orb API response to flattened line items for a single day
func (s *Server) formatLineItems(data *OrbCostData) ([]*gpb.LineItem, error) {
	var allLineItems []*gpb.LineItem

	// Process per-price costs
	for _, priceCost := range data.PerPriceCosts {
		categoryName := priceCost.Price.Name

		// Get currency from Orb response
		currency := priceCost.Price.Currency

		// Get unit amounts from matrix config if available
		// Key is "dimension_value_0|dimension_value_1"
		unitAmounts := make(map[string]string) // Store as strings to avoid float precision issues
		if priceCost.Price.MatrixConfig != nil {
			for _, mv := range priceCost.Price.MatrixConfig.MatrixValues {
				if len(mv.DimensionValues) >= 2 {
					key := mv.DimensionValues[0] + "|" + mv.DimensionValues[1]
					unitAmounts[key] = mv.UnitAmount
				} else if len(mv.DimensionValues) == 1 {
					key := mv.DimensionValues[0] + "|"
					unitAmounts[key] = mv.UnitAmount
				}
			}
		}

		// Process price groups (line items)
		var categoryLineItems []*gpb.LineItem
		for _, group := range priceCost.PriceGroups {
			quantity := group.Quantity

			// Skip items with no quantity
			if quantity <= 0 {
				continue
			}

			// Parse total cost directly to Money
			totalCost, err := parseStringToMoney(group.Total, currency)
			if err != nil {
				return nil, fmt.Errorf("failed to parse total cost for group %s: %w", group.GroupingValue, err)
			}

			// Get unit amount from matrix config if available
			var unitAmount *money.Money
			key := group.GroupingValue + "|" + group.SecondaryGroupingValue
			if unitAmountStr, exists := unitAmounts[key]; exists {
				unitAmount, err = parseStringToMoney(unitAmountStr, currency)
				if err != nil {
					return nil, fmt.Errorf("failed to parse unit amount for group %s: %w", group.GroupingValue, err)
				}
			}
			// If unit amount not in matrix config, leave it nil

			lineItem := &gpb.LineItem{
				Category:               stringPtr(categoryName),
				GroupingKey:            stringPtr(group.GroupingKey),
				GroupingValue:          stringPtr(group.GroupingValue),
				SecondaryGroupingKey:   stringPtr(group.SecondaryGroupingKey),
				SecondaryGroupingValue: stringPtr(group.SecondaryGroupingValue),
				Quantity:               quantity,
				UnitAmount:             unitAmount,
				TotalCost:              totalCost,
			}
			categoryLineItems = append(categoryLineItems, lineItem)
		}

		// Handle edge case: no price groups but category has quantity/total
		if len(categoryLineItems) == 0 && len(priceCost.PriceGroups) == 0 && priceCost.Total != "" && priceCost.Total != "0" && priceCost.Quantity > 0 {
			// Parse category total
			totalCost, err := parseStringToMoney(priceCost.Total, currency)
			if err != nil {
				return nil, fmt.Errorf("failed to parse category total: %w", err)
			}

			// Get unit amount from unit config if available
			var unitAmount *money.Money
			if priceCost.Price.UnitConfig != nil && priceCost.Price.UnitConfig.UnitAmount != "" {
				unitAmount, err = parseStringToMoney(priceCost.Price.UnitConfig.UnitAmount, currency)
				if err != nil {
					return nil, fmt.Errorf("failed to parse unit config amount: %w", err)
				}
			}
			// If unit amount not in unit config, leave it nil

