package accountwatcher

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/cognitoidentityprovider"
	"github.com/aws/aws-sdk-go-v2/service/cognitoidentityprovider/types"
	cognitotypes "github.com/aws/aws-sdk-go-v2/service/cognitoidentityprovider/types"
	"github.com/fw-ai/fireworks/control_plane/pkg/database"
	"github.com/fw-ai/fireworks/control_plane/pkg/fwerror"
	gpb "github.com/fw-ai/fireworks/control_plane/protos/generated/gateway"
	"github.com/fw-ai/fireworks/go/maputil"
	resourcename "github.com/fw-ai/fireworks/go/resource_name"
	"github.com/fw-ai/fireworks/go/sliceutil"
	"github.com/rs/zerolog/log"
)

// reconcileIdentityProviderAndStatus reconciles the identity provider and its status.
func (w *AccountWatcher) reconcileIdentityProviderAndStatus(ctx context.Context, accountID, identityProviderID string) {
	l := log.Ctx(ctx).With().
		Str("account_id", accountID).
		Str("identity_provider_id", identityProviderID).
		Logger()
	ctx = l.WithContext(ctx)
	l.Info().Msg("Reconciling identity provider")

	var dba database.Account
	err := dba.Populate(w.db, resourcename.NewAccountName(accountID))
	if err != nil {
		l.Error().Err(err).Msg("Error getting account from database")
		return
	}

	var idp database.IdentityProvider
	ipn := resourcename.NewIdentityProviderName(accountID, identityProviderID)
	err = idp.Populate(w.db, ipn)
	if err != nil {
		l.Error().Err(err).Msg("Error getting identity provider from database")
		return
	}
	oldState := idp.State

	newState, err := w.reconcileIdentityProvider(ctx, &dba, &idp)
	if newState == 0 {
		newState = idp.State
	}

	if newState == gpb.IdentityProvider_DELETING && err == nil {
		l.Info().Msg("Deleting identity provider from database")
		result := w.db.Delete(&idp)
		if result.Error != nil {
			l.Error().Err(result.Error).Msg("Error deleting identity provider from database")
			return
		}
		w.reconcilers.Delete(identityProviderReconcilerID(accountID, identityProviderID))
		return
	}

	status := fwerror.LogAndGetStatus(err)
	shouldUpdateDB := newState != idp.State ||
		gpb.Code(status.Code()) != idp.Status.Code ||
		status.Message() != idp.Status.Message

	if shouldUpdateDB {
		l.Info().Str("state", newState.String()).Msg("Writing identity provider status to database")
		result := w.db.Model(&idp).Updates(map[string]interface{}{
			"State":          newState,
			"Status_Code":    gpb.Code(status.Code()),
			"Status_Message": status.Message(),
		})
		if result.Error != nil {
			l.Error().Err(result.Error).Msg("Error writing identity provider status to database")
			return
		}
	} else {
		l.Info().Msg("Skipping writing identity provider status to database since no diff")
	}
	if newState != oldState {
		l.Info().
			Str("control_plane_audit_log", "true").
			Str("source", "account_watcher").
			Str("resource", ipn.String()).
			Msgf("State transitioned from %s to %s", oldState.String(), newState.String())
	}
}

// reconcileIdentityProvider ensures that identity providers are properly configured for accounts that have them.
func (w *AccountWatcher) reconcileIdentityProvider(ctx context.Context, dba *database.Account, idp *database.IdentityProvider) (gpb.IdentityProvider_State, error) {
	l := *log.Ctx(ctx)
	l.Info().Str("state", idp.State.String()).Msg("Current identity provider state")

	switch idp.State {
	case gpb.IdentityProvider_CREATING, gpb.IdentityProvider_UPDATING, gpb.IdentityProvider_READY:
		err := w.reconcileIdentityProviderResources(ctx, dba, idp)
		if err != nil {
			return 0, fwerror.WrapL(l, "error reconciling identity provider AWS resources: %w", err)
		}
		return gpb.IdentityProvider_READY, nil

	case gpb.IdentityProvider_DELETING:
		err := w.deleteUserPoolIdentityProvider(ctx, dba.AccountId, idp.IdentityProviderId)
		if err != nil {
			return 0, fwerror.WrapL(l, "error deleting identity provider AWS resources: %w", err)
		}
		return gpb.IdentityProvider_DELETING, nil

	default:
		return 0, fwerror.WrapL(l, "unknown identity provider state: %v", idp.State)
	}
}

// reconcileIdentityProviderResources ensures that identity providers are properly configured for accounts that have them.
func (w *AccountWatcher) reconcileIdentityProviderResources(ctx context.Context, account *database.Account, idp *database.IdentityProvider) error {
	l := *log.Ctx(ctx)

	userPoolName := account.AccountId
	tenantDomains := idp.TenantDomains

	// Reconcile user pool
	userPoolId, err := w.reconcileUserPool(ctx, account, userPoolName, tenantDomains)
	if err != nil {
		return fwerror.WrapL(l, "error reconciling user pool: %w", err)
	}

	// Reconcile identity provider
	err = w.reconcileIdentityProviderInstance(ctx, userPoolId, idp)
	if err != nil {
		return fwerror.WrapL(l, "error reconciling identity provider: %w", err)
	}

	// Reconcile user pool client

	clientId, err := w.reconcileUserPoolClient(ctx, userPoolId, userPoolName, idp, account)
	if err != nil {
		return fwerror.WrapL(l, "error reconciling user pool client: %w", err)
	}

	// Reconcile user pool domain
	domainPrefix, err := w.reconcileUserPoolDomain(ctx, userPoolId, account)
	if err != nil {
		return fwerror.WrapL(l, "error reconciling user pool domain: %w", err)
	}

	// Update identity provider configuration
	err = idp.Populate(w.db, resourcename.NewIdentityProviderName(account.AccountId, idp.IdentityProviderId))
	if err != nil {
		return fwerror.WrapL(l, "failed to get identity provider %s: %w", idp.IdentityProviderId, err)
	}

	result := w.db.Model(&idp).Updates(&database.IdentityProvider{
		DomainUrl: fmt.Sprintf("https://%s.auth.us-west-2.amazoncognito.com", domainPrefix),
		IssuerUrl: fmt.Sprintf("https://cognito-idp.us-west-2.amazonaws.com/%s", userPoolId),
		ClientId:  clientId,
	})
	if result.Error != nil {
		return fwerror.WrapL(l, "failed to update identity provider cognito resources: %w", result.Error)
	}

	return nil
}

// reconcileUserPool ensures the user pool exists and is properly configured.
func (w *AccountWatcher) reconcileUserPool(ctx context.Context, account *database.Account, userPoolName string, tenantDomains []string) (string, error) {
	l := *log.Ctx(ctx)

	existingUserPoolId, err := w.GetUserPoolByAccountID(ctx, account.AccountId)
	if err != nil {
		return "", fwerror.WrapL(l, "error discovering user pool by account ID: %w", err)
	}

	if existingUserPoolId != "" {
		err = w.reconcileUserPoolConfig(ctx, existingUserPoolId, account.AccountId, tenantDomains)
		if err != nil {
			return "", fwerror.WrapL(l, "error reconciling user pool configuration: %w", err)
		}
		return existingUserPoolId, nil
	}

	result, err := w.awsClient.CognitoClient.CreateUserPool(ctx, &cognitoidentityprovider.CreateUserPoolInput{
		PoolName: &userPoolName,
		Policies: &types.UserPoolPolicyType{
			PasswordPolicy: &types.PasswordPolicyType{
				MinimumLength:    aws.Int32(8),
				RequireLowercase: true,
				RequireNumbers:   true,
				RequireSymbols:   true,
				RequireUppercase: true,
			},
		},
		AutoVerifiedAttributes: []types.VerifiedAttributeType{types.VerifiedAttributeTypeEmail},
		UsernameAttributes:     []types.UsernameAttributeType{types.UsernameAttributeTypeEmail},
		AdminCreateUserConfig: &types.AdminCreateUserConfigType{
			AllowAdminCreateUserOnly: true,
		},
		AccountRecoverySetting: &types.AccountRecoverySettingType{
			RecoveryMechanisms: []types.RecoveryOptionType{
				{
					Name:     types.RecoveryOptionNameTypeAdminOnly,
					Priority: aws.Int32(1),
				},
			},
		},
		UserPoolTags: map[string]string{
			"Account-ID":     account.AccountId,
			"Tenant-Domains": strings.Join(tenantDomains, " "),
		},
		LambdaConfig: &types.LambdaConfigType{
			PreSignUp:          aws.String("arn:aws:lambda:us-west-2:794651314743:function:FireworksSharedDomainValidation"),
			PreTokenGeneration: aws.String("arn:aws:lambda:us-west-2:794651314743:function:FireworksSharedTokenGeneration"),
		},
	})
	if err != nil {
		return "", fwerror.WrapL(l, "failed to create UserPool via AWS SDK: %w", err)
	}
	userPoolId := *result.UserPool.Id
	l.Info().Str("user_pool_id", userPoolId).Msg("Created new user pool")
	return userPoolId, nil
}

// reconcileIdentityProviderInstance ensures the identity provider exists and is properly configured.
func (w *AccountWatcher) reconcileIdentityProviderInstance(ctx context.Context, userPoolId string, idp *database.IdentityProvider) error {
	l := *log.Ctx(ctx)

	existingProvider, err := w.GetIdentityProvider(ctx, userPoolId, idp.IdentityProviderId)
	if err != nil {
		return fwerror.WrapL(l, "error discovering identity provider: %w", err)
	}

	if existingProvider != nil {
		err = w.reconcileIdentityProviderConfig(ctx, userPoolId, idp, existingProvider)
		if err != nil {
			return fwerror.WrapL(l, "error reconciling identity provider config: %w", err)
		}
		return nil
	}

	err = w.createUserPoolIdentityProvider(ctx, userPoolId, idp)
	if err != nil {
		return fwerror.WrapL(l, "failed to create user pool identity provider: %w", err)
	}
	l.Info().Str("provider_name", idp.IdentityProviderId).Msg("Created new identity provider")
	return nil
}

// reconcileUserPoolClient ensures the user pool client exists and is properly configured.
func (w *AccountWatcher) reconcileUserPoolClient(ctx context.Context, userPoolId, userPoolName string, idp *database.IdentityProvider, account *database.Account) (string, error) {
	l := *log.Ctx(ctx)

	clientName := fmt.Sprintf("%s-client", userPoolName)
	existingClient, err := w.GetUserPoolClient(ctx, userPoolId, clientName)
	if err != nil {
		return "", fwerror.WrapL(l, "error discovering user pool client: %w", err)
	}

	if existingClient != nil {
		clientId := *existingClient.ClientId
		err = w.reconcileUserPoolClientConfig(ctx, userPoolId, existingClient, userPoolName, []string{idp.IdentityProviderId}, account.AccountId)
		if err != nil {
			return ""

, fwerror.WrapL(l, "error reconciling user pool client config: %w", err)
		}
		return clientId, nil
	}

	clientId, err := w.createUserPoolClient(ctx, userPoolId, userPoolName, []string{idp.IdentityProviderId}, account.AccountId)
	if err != nil {
		return "", fwerror.WrapL(l, "failed to create user pool client: %w", err)
	}
	l.Info().Str("client_name", clientName).Str("client_id", clientId).Msg("Created new user pool client")
	return clientId, nil
}

// reconcileUserPoolDomain ensures the user pool domain exists and is properly configured.
func (w *AccountWatcher) reconcileUserPoolDomain(ctx context.Context, userPoolId string, account *database.Account) (string, error) {
	l := *log.Ctx(ctx)

	existingDomainName, err := w.GetUserPoolDomain(ctx, account.AccountId)
	if err != nil {
		return "", fwerror.WrapL(l, "error discovering user pool domain: %w", err)
	}

	if existingDomainName != "" {
		err = w.reconcileUserPoolDomainConfig(ctx, userPoolId, existingDomainName)
		if err != nil {
			return "", fwerror.WrapL(l, "error reconciling user pool domain config: %w", err)
		}
		return existingDomainName, nil
	}

	domainPrefix := fmt.Sprintf("fireworks-%s", account.AccountId)

	// If the user pool already has a different / stale domain bound to it, a
	// plain CreateUserPoolDomain will be rejected with
	//   InvalidParameterException: User pool already has a domain configured
	// because each Cognito user pool can have at most one hosted-UI domain.
	// Disassociate whatever is currently bound first, then create the desired
	// domain. DescribeUserPool reports the currently-bound domain via
	// UserPool.Domain (empty if none).
	if err := w.clearStaleUserPoolDomain(ctx, userPoolId); err != nil {
		return "", fwerror.WrapL(l, "error clearing stale user pool domain before create: %w", err)
	}

	_, err = w.awsClient.CognitoClient.CreateUserPoolDomain(ctx, &cognitoidentityprovider.CreateUserPoolDomainInput{
		Domain:     aws.String(domainPrefix),
		UserPoolId: aws.String(userPoolId),
	})
	if err != nil {
		return "", fwerror.WrapL(l, "failed to create UserPool domain: %w", err)
	}
	l.Info().Str("domain_name", domainPrefix).Msg("Created new user pool domain")
	return domainPrefix, nil
}

// clearStaleUserPoolDomain looks up whatever domain is currently bound to the
// given user pool (via DescribeUserPool) and disassociates it. It is a no-op
// if the user pool has no domain bound. Cognito's two "already gone" error
// shapes (ResourceNotFoundException and InvalidParameterException "No such
// domain or user pool exists") are treated as benign.
func (w *AccountWatcher) clearStaleUserPoolDomain(ctx context.Context, userPoolId string) error {
	l := *log.Ctx(ctx)

	upDesc, err := w.awsClient.CognitoClient.DescribeUserPool(ctx, &cognitoidentityprovider.DescribeUserPoolInput{
		UserPoolId: &userPoolId,
	})
	if err != nil {
		return fwerror.WrapL(l, "failed to describe user pool %s: %w", userPoolId, err)
	}
	if upDesc.UserPool == nil || upDesc.UserPool.Domain == nil || *upDesc.UserPool.Domain == "" {
		return nil
	}

	boundDomain := *upDesc.UserPool.Domain
	l.Warn().Str("bound_domain", boundDomain).Str("user_pool_id", userPoolId).Msg("Deleting stale domain bound to user pool")
	_, delErr := w.awsClient.CognitoClient.DeleteUserPoolDomain(ctx, &cognitoidentityprovider.DeleteUserPoolDomainInput{
		Domain:     &boundDomain,
		UserPoolId: &userPoolId,
	})
	if delErr != nil && !isCognitoDomainNotFound(delErr) {
		return fwerror.WrapL(l, "failed to delete stale domain %s on user pool %s: %w", boundDomain, userPoolId, delErr)
	}
	return nil
}

// reconcileUserPoolConfig ensures the user pool configuration is up to date, including tags.
func (w *AccountWatcher) reconcileUserPoolConfig(ctx context.Context, userPoolId, accountId string, tenantDomains []string) error {
	l := *log.Ctx(ctx)

	// Get current user pool configuration
	describeOutput, err := w.awsClient.CognitoClient.DescribeUserPool(ctx, &cognitoidentityprovider.DescribeUserPoolInput{
		UserPoolId: &userPoolId,
	})
	if err != nil {
		return fwerror.WrapL(l, "error describing user pool: %w", err)
	}

	// Get current tags
	tagsResponse, err := w.awsClient.CognitoClient.ListTagsForResource(ctx, &cognitoidentityprovider.ListTagsForResourceInput{
		ResourceArn: describeOutput.UserPool.Arn,
	})
	if err != nil {
		return fwerror.WrapL(l, "error getting user pool tags: %w", err)
	}

	currentTags := tagsResponse.Tags
	desiredTenantDomains := strings.Join(tenantDomains, " ")
	currentTenantDomains := currentTags["Tenant-Domains"]

	if currentTenantDomains != desiredTenantDomains {

		_, err = w.awsClient.CognitoClient.TagResource(ctx, &cognitoidentityprovider.TagResourceInput{
			ResourceArn: describeOutput.UserPool.Arn,
			Tags: map[string]string{
				"Account-ID":     accountId,
				"Tenant-Domains": desiredTenantDomains,
			},
		})
		if err != nil {
			return fwerror.WrapL(l, "error updating user pool tags: %w", err)
		}
		l.Info().
			Str("user_pool_id", userPoolId).
			Str("tenant_dom

ains", desiredTenantDomains).
			Msg("Updated user pool tenant domains")
	} else {
		l.Info().Str("user_pool_id", userPoolId).Msg("User pool configuration is already up to date")
	}

	return nil
}

func identityProviderReconcilerID(accountID, identityProviderID string) string {
	return fmt.Sprintf("identity-provider/%s/%s", accountID, identityProviderID)
}

// GetUserPoolByAccountID searches for a user pool with the specific account ID.
func (w *AccountWatcher) GetUserPoolByAccountID(ctx context.Context, accountID string) (string, error) {
	l := *log.Ctx(ctx)
	l.Info().Str("account_id", accountID).Msg("Searching for user pool by account ID")

	paginator := cognitoidentityprovider.NewListUserPoolsPaginator(w.awsClient.CognitoClient, &cognitoidentityprovider.ListUserPoolsInput{
		MaxResults: aws.Int32(60),
	})

	for paginator.HasMorePages() {
		output, err := paginator.NextPage(ctx)
		if err != nil {
			return "", fwerror.WrapL(l, "error listing user pools: %w", err)
		}

		for _, userPool := range output.UserPools {
			// AWS API can return user pools with nil Id fields in rare cases
			// (e.g., during creation/deletion states or API inconsistencies)
			if userPool.Id == nil {
				continue
			}

			userPoolId := *userPool.Id

			describeOutput, err := w.awsClient.CognitoClient.DescribeUserPool(ctx, &cognitoidentityprovider.DescribeUserPoolInput{
				UserPoolId: &userPoolId,
			})
			if err != nil {
				l.Warn().Str("user_pool_id", userPoolId).Err(err).Msg("Failed to describe user pool, skipping")
				continue
			}

			if describeOutput.UserPool.Arn == nil {
				l.Warn().Str("user_pool_id", userPoolId).Msg("User pool ARN is nil, skipping")
				continue
			}

			tagsResponse, err := w.awsClient.CognitoClient.ListTagsForResource(ctx, &cognitoidentityprovider.ListTagsForResourceInput{
				ResourceArn: describeOutput.UserPool.Arn,
			})
			if err != nil {
				l.Warn().Str("user_pool_id", userPoolId).Err(err).Msg("Failed to get tags for user pool, skipping")
				continue
			}

			if tagsResponse.Tags["Account-ID"] == accountID {
				l.Info().Str("user_pool_id", userPoolId).Interface("tags", tagsResponse.Tags).Msg("Found user pool with matching account ID")
				return userPoolId, nil
			}
		}
	}

	l.Info().Msg("No user pools found with matching account ID")
	return "", nil
}

func (w *AccountWatcher) GetIdentityProvider(ctx context.Context, userPoolId, providerName string) (*cognitotypes.ProviderDescription, error) {
	l := *log.Ctx(ctx)
	l.Info().Str("user_pool_id", userPoolId).Str("provider_name", providerName).Msg("Searching for existing identity provider")

	paginator := cognitoidentityprovider.NewListIdentityProvidersPaginator(w.awsClient.CognitoClient, &cognitoidentityprovider.ListIdentityProvidersInput{
		UserPoolId: &userPoolId,
	})

	for paginator.HasMorePages() {
		output, err := paginator.NextPage(ctx)
		if err != nil {
			return nil, fwerror.WrapL(l, "error listing identity providers for user pool %s: %w", userPoolId, err)
		}

		for _, provider := range output.Providers {
			if provider.ProviderName != nil && *provider.ProviderName == providerName {
				l.Info().Str("provider_name", providerName).Str("provider_type", string(provider.ProviderType)).Msg("Found existing identity provider")
				return &provider, nil
			}
		}
	}

	l.Info().Str("provider_name", providerName).Msg("Identity provider not found")
	return nil, nil
}

func (w *AccountWatcher) GetUserPoolClient(ctx context.Context, userPoolId, clientName string) (*cognitotypes.UserPoolClientDescription, error) {
	l := *log.Ctx(ctx)
	l.Info().Str("user_pool_id", userPoolId).Str("client_name", clientName).Msg("Searching for existing user pool client")

	paginator := cognitoidentityprovider.NewListUserPoolClientsPaginator(w.awsClient.CognitoClient, &cognitoidentityprovider.ListUserPoolClientsInput{
		UserPoolId: &userPoolId,
	})

	for paginator.HasMorePages() {
		output, err := paginator.NextPage(ctx)
		if err != nil {
			return nil, fwerror.WrapL(l, "error listing user pool clients for user pool %s: %w", userPoolId, err)
		}

		for _, client := range output.UserPoolClients {
			if client.ClientName != nil && *client.ClientName == clientName {
				l.Info().Str("client_name", clientName).Str("client_id", *client.ClientId).Msg("Found existing user pool client")
				return &client, nil
			}
		}
	}

	l.Info().Str("client_name", clientName).Msg("User pool client not found")
	return nil, nil
}

// GetUserPoolDomain checks if a domain already exists using AWS-first discovery.
func (w *AccountWatcher) GetUserPoolDomain(ctx context.Context, accountId string) (string, error) {
	l := *log.Ctx(ctx)

	domainName := fmt.Sprintf("fireworks-%s", accountId)
	resp, err := w.awsClient.CognitoClient.DescribeUserPoolDomain(ctx, &cognitoidentityprovider.DescribeUserPoolDomainInput{
		Domain: &domainName,
	})
	if err == nil {
		// DescribeUserPoolDomain returns a non-nil DomainDescription with all
		// fields nil when the domain does not actually exist (it does NOT
		// ret

urn a ResourceNotFoundException). Treat that as "not found".
		if resp.DomainDescription == nil ||
			resp.DomainDescription.Domain == nil ||
			resp.DomainDescription.UserPoolId == nil {
			l.Info().Str("domain", domainName).Msg("Domain not found (empty DomainDescription from AWS)")
			return "", nil
		}
		return domainName, nil
	}

	var notFoundErr *cognitotypes.ResourceNotFoundException
	if !errors.As(err, &notFoundErr) {
		return "", fwerror.WrapL(l, "error checking domain %s: %w", domainName, err)
	}

	return "", nil
}

// defaultSamlEmailAttribute is the SAML attribute name used by Azure AD, ADFS, and Okta.
const defaultSamlEmailAttribute = "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress"

// getIdentityProviderConfig builds the desired provider configuration based on database settings.
func (w *AccountWatcher) getIdentityProviderConfig(idp *database.IdentityProvider) (map[string]string, map[string]string) {
	var providerDetails map[string]string
	var attributeMapping map[string]string

	switch idp.Config {
	case "SamlConfig":
		if idp.SamlConfig != nil {
			if idp.SamlConfig.MetadataXml != "" {
				providerDetails = map[string]string{
					"MetadataFile": idp.SamlConfig.MetadataXml,
				}
			} else {
				providerDetails = map[string]string{
					"MetadataURL": idp.SamlConfig.MetadataUrl,
				}
			}
			providerDetails["IDPInit"] = fmt.Sprintf("%t", idp.EnableIdpInitiatedSso)
		}
		emailAttr := defaultSamlEmailAttribute
		if idp.SamlConfig != nil && idp.SamlConfig.SamlEmailAttribute != "" {
			emailAttr = idp.SamlConfig.SamlEmailAttribute
		}
		attributeMapping = map[string]string{
			"email": emailAttr,
		}
	case "OidcConfig":
		if idp.OidcConfig != nil {
			providerDetails = map[string]string{
				"client_id":                     idp.OidcConfig.ClientId,
				"client_secret":                 idp.OidcConfig.ClientSecret,
				"oidc_issuer":                   idp.OidcConfig.IssuerUrl,
				"authorize_scopes":              "openid email",
				"attributes_request_method":     "GET",
				"attributes_url_add_attributes": "false", // Match Terraform setting
			}
		}
		attributeMapping = map[string]string{
			"email":    "email",
			"username": "sub",
		}
	}

	return providerDetails, attributeMapping
}

