// createUserPoolClient creates a new user pool client.
func (w *AccountWatcher) createUserPoolClient(ctx context.Context, userPoolId, userPoolName string, supportedIdentityProviders []string, accountId string) (string, error) {
	l := *log.Ctx(ctx)

	desiredConfig := w.getUserPoolClientConfig(userPoolName, supportedIdentityProviders, accountId)

	result, err := w.awsClient.CognitoClient.CreateUserPoolClient(ctx, &cognitoidentityprovider.CreateUserPoolClientInput{
		UserPoolId:                      aws.String(userPoolId),
		ClientName:                      aws.String(fmt.Sprintf("%s-client", userPoolName)),
		GenerateSecret:                  false, // Native client - no client secret
		ExplicitAuthFlows:               desiredConfig.ExplicitAuthFlows,
		SupportedIdentityProviders:      desiredConfig.SupportedIdentityProviders,
		CallbackURLs:                    desiredConfig.CallbackURLs,
		LogoutURLs:                      desiredConfig.LogoutURLs,
		AllowedOAuthFlows:               desiredConfig.AllowedOAuthFlows,
		AllowedOAuthScopes:              desiredConfig.AllowedOAuthScopes,
		AllowedOAuthFlowsUserPoolClient: desiredConfig.AllowedOAuthFlowsUserPoolClient,
		RefreshTokenValidity:            desiredConfig.RefreshTokenValidity,
		AccessTokenValidity:             desiredConfig.AccessTokenValidity,
		IdTokenValidity:                 desiredConfig.IdTokenValidity,
		TokenValidityUnits:              desiredConfig.TokenValidityUnits,
		ReadAttributes:                  desiredConfig.ReadAttributes,
		WriteAttributes:                 desiredConfig.WriteAttributes,
	})
	if err != nil {
		return "", fwerror.WrapL(l, "failed to create UserPool client: %w", err)
	}
	return *result.UserPoolClient.ClientId, nil
}

// createUserPoolIdentityProvider creates the identity provider in the user pool.
func (w *AccountWatcher) createUserPoolIdentityProvider(ctx context.Context, userPoolId string, idp *database.IdentityProvider) error {
	l := *log.Ctx(ctx)

	providerDetails, attributeMapping := w.getIdentityProviderConfig(idp)

	var providerType types.IdentityProviderTypeType
	switch idp.Config {
	case "SamlConfig":
		providerType = types.IdentityProviderTypeTypeSaml
	case "OidcConfig":
		providerType = types.IdentityProviderTypeTypeOidc
	default:
		return fwerror.WrapL(l, "unsupported identity provider config type: %s", idp.Config)
	}

	_, err := w.awsClient.CognitoClient.CreateIdentityProvider(ctx, &cognitoidentityprovider.CreateIdentityProviderInput{
		UserPoolId:       aws.String(userPoolId),
		ProviderName:     aws.String(idp.IdentityProviderId),
		ProviderType:     providerType,
		ProviderDetails:  providerDetails,
		AttributeMapping: attributeMapping,
	})
	if err != nil {
		return fwerror.WrapL(l, "failed to create UserPool identity provider: %w", err)
	}
	return nil
}

// reconcileIdentityProviderConfig compares current vs desired identity provider configuration and updates if needed.
func (w *AccountWatcher) reconcileIdentityProviderConfig(ctx context.Context, userPoolId string, idp *database.IdentityProvider, existingProvider *cognitotypes.ProviderDescription) error {
	l := *log.Ctx(ctx)

	currentConfig, err := w.awsClient.CognitoClient.DescribeIdentityProvider(ctx, &cognitoidentityprovider.DescribeIdentityProviderInput{
		UserPoolId:   &userPoolId,
		ProviderName: existingProvider.ProviderName,
	})
	if err != nil {
		return fwerror.WrapL(l, "error describing identity provider: %w", err)
	}

	desiredProviderDetails, desiredAttributeMapping := w.getIdentityProviderConfig(idp)

	// Remove AWS-generated fields that should be ignored from current config.
	// IDPInit is always explicitly set in desired config for SAML providers, so it's never filtered here.
	currentDetails := make(map[string]string)
	for key, value := range currentConfig.IdentityProvider.ProviderDetails {
		if key == "ActiveEncryptionCertificate" || key == "SSORedirectBindingURI" || key == "SLORedirectBindingURI" {
			continue
		}
		currentDetails[key] = value
	}

	if maputil.Equals(currentDetails, desiredProviderDetails) &&
		maputil.Equals(currentConfig.IdentityProvider.AttributeMapping, desiredAttributeMapping) {
		l.Info().Msg("Identity provider configuration is already up

 to date")
		return nil
	}

	_, err = w.awsClient.CognitoClient.UpdateIdentityProvider(ctx, &cognitoidentityprovider.UpdateIdentityProviderInput{
		UserPoolId:       &userPoolId,
		ProviderName:     existingProvider.ProviderName,
		ProviderDetails:  desiredProviderDetails,
		AttributeMapping: desiredAttributeMapping,
	})
	if err != nil {
		return fwerror.WrapL(l, "error updating identity provider: %w", err)
	}

	return nil
}

// reconcileUserPoolClientConfig compares current vs desired client configuration and updates if needed.
func (w *AccountWatcher) reconcileUserPoolClientConfig(ctx context.Context, userPoolId string, existingClient *cognitotypes.UserPoolClientDescription, userPoolName string, supportedIdentityProviders []string, accountId string) error {
	l := *log.Ctx(ctx)

	currentConfig, err := w.awsClient.CognitoClient.DescribeUserPoolClient(ctx, &cognitoidentityprovider.DescribeUserPoolClientInput{
		UserPoolId: &userPoolId,
		ClientId:   existingClient.ClientId,
	})
	if err != nil {
		return fwerror.WrapL(l, "error describing user pool client: %w", err)
	}

	desiredConfig := w.getUserPoolClientConfig(userPoolName, supportedIdentityProviders, accountId)

	needsUpdate := !sliceutil.SameElements(currentConfig.UserPoolClient.SupportedIdentityProviders, desiredConfig.SupportedIdentityProviders) ||
		!sliceutil.SameElements(currentConfig.UserPoolClient.CallbackURLs, desiredConfig.CallbackURLs) ||
		!sliceutil.SameElements(currentConfig.UserPoolClient.LogoutURLs, desiredConfig.LogoutURLs) ||
		!sliceutil.SameElements(currentConfig.UserPoolClient.AllowedOAuthScopes, desiredConfig.AllowedOAuthScopes)

	if !needsUpdate {
		l.Info().Msg("User pool client configuration is already up to date")
		return nil
	}

	_, err = w.awsClient.CognitoClient.UpdateUserPoolClient(ctx, &cognitoidentityprovider.UpdateUserPoolClientInput{
		UserPoolId:                      &userPoolId,
		ClientId:                        existingClient.ClientId,
		ClientName:                      existingClient.ClientName, // Keep existing name
		SupportedIdentityProviders:      desiredConfig.SupportedIdentityProviders,
		CallbackURLs:                    desiredConfig.CallbackURLs,
		LogoutURLs:                      desiredConfig.LogoutURLs,
		AllowedOAuthFlows:               desiredConfig.AllowedOAuthFlows,
		AllowedOAuthScopes:              desiredConfig.AllowedOAuthScopes,
		AllowedOAuthFlowsUserPoolClient: desiredConfig.AllowedOAuthFlowsUserPoolClient,
		ExplicitAuthFlows:               desiredConfig.ExplicitAuthFlows,
		RefreshTokenValidity:            desiredConfig.RefreshTokenValidity,
		AccessTokenValidity:             desiredConfig.AccessTokenValidity,
		IdTokenValidity:                 desiredConfig.IdTokenValidity,
		TokenValidityUnits:              desiredConfig.TokenValidityUnits,
		ReadAttributes:                  desiredConfig.ReadAttributes,
		WriteAttributes:                 desiredConfig.WriteAttributes,
	})
	if err != nil {
		return fwerror.WrapL(l, "error updating user pool client: %w", err)
	}
	return nil
}

