func createTestDeploymentReplicaEvent(t *testing.T, s *server, accountId, deploymentId, eventId string, eventType gpb.DeploymentReplicaEvent_Type, status gpb.DeploymentReplicaEvent_Status, duration time.Duration) *database.DeploymentReplicaEvent {
	event := &database.DeploymentReplicaEvent{
		DeploymentReplicaEventName: *resourcename.NewDeploymentReplicaEventName(accountId, deploymentId, eventId),
		Type:                       eventType,
		Status:                     status,
		Duration:                   duration.Nanoseconds(),
		StartTime:                  s.now().Add(-duration),
		EndTime:                    s.now(),
		Placement: &database.Placement{
			Region: gpb.Region_US_IOWA_1,
		},
		InitialReplicaState: &gpb.DeploymentReplicaEvent_ReplicaState{
			Desired: 1,
			Current: 1,
			Min:     1,
		},
		TargetReplicaState: &gpb.DeploymentReplicaEvent_ReplicaState{
			Desired: 2,
			Current: 2,
			Min:     1,
		},
	}
	result := s.DB().Create(event)
	require.NoError(t, result.Error)
	return event
}

