func TestListDeploymentReplicaEvents_WithFilter(t *testing.T) {
	s := newTestServer(t)

	// Create test events with different types
	createTestDeploymentReplicaEvent(t, s, "filter-account", "deployment-1", "filter-event-1",
		gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP, gpb.DeploymentReplicaEvent_FINISHED, 30*time.Second)
	reservedEvent := createTestDeploymentReplicaEvent(t, s, "filter-account", "deployment-1", "filter-event-2",
		gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_DOWN, gpb.DeploymentReplicaEvent_FINISHED, 60*time.Second)
	reservedEvent.Reserved = true
	require.NoError(t, s.DB().Save(reservedEvent).Error)
	createTestDeploymentReplicaEvent(t, s, "filter-account", "deployment-1", "filter-event-3",
		gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP, gpb.DeploymentReplicaEvent_ONGOING, 90*time.Second)

	// Filter by type
	resp, err := s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `type = "AUTOMATIC_SCALE_UP" AND account_id = "filter-account"`,
	})
	require.NoError(t, err)
	assert.Len(t, resp.DeploymentReplicaEvents, 2)
	for _, e := range resp.DeploymentReplicaEvents {
		assert.Equal(t, gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP, e.Type)
	}

	// Filter by status
	resp, err = s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `status = "ONGOING" AND account_id = "filter-account"`,
	})
	require.NoError(t, err)
	assert.Len(t, resp.DeploymentReplicaEvents, 1)
	assert.Equal(t, gpb.DeploymentReplicaEvent_ONGOING, resp.DeploymentReplicaEvents[0].Status)

	// Filter by reserved flag
	resp, err = s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `reserved = true AND account_id = "filter-account"`,
	})
	require.NoError(t, err)
	require.Len(t, resp.DeploymentReplicaEvents, 1)
	assert.True(t, resp.DeploymentReplicaEvents[0].Reserved)
	assert.Equal(t, reservedEvent.Name(), resp.DeploymentReplicaEvents[0].Name)

	resp, err = s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `reserved = false AND account_id = "filter-account"`,
	})
	require.NoError(t, err)
	require.Len(t, resp.DeploymentReplicaEvents, 2)
	for _, event := range resp.DeploymentReplicaEvents {
		assert.False(t, event.Reserved)
	}
}

func TestListDeploymentReplicaEvents_FilterByDuration(t *testing.T) {
	s := newTestServer(t)

	// Create events with different durations
	createTestDeploymentReplicaEvent(t, s, "duration-filter-account", "deployment-1", "duration-event-1",
		gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP, gpb.DeploymentReplicaEvent_FINISHED, 30*time.Second)
	createTestDeploymentReplicaEvent(t, s, "duration-filter-account", "deployment-1", "duration-event-2",
		gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP, gpb.DeploymentReplicaEvent_FINISHED, 2*time.Minute)
	createTestDeploymentReplicaEvent(t, s, "duration-filter-account", "deployment-1", "duration-event-3",
		gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP, gpb.DeploymentReplicaEvent_FINISHED, 5*time.Minute)

	// Filter by duration greater than 1 minute (60 billion nanoseconds)
	resp, err := s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `account_id = "duration-filter-account" AND duration > 60000000000`,
	})
	require.NoError(t, err)
	assert.Len(t, resp.DeploymentReplicaEvents, 2)
	for _, e := range resp.DeploymentReplicaEvents {
		assert.Greater(t, e.Duration.AsDuration(), time.Minute)
	}

	// Filter by duration less than 1 minute
	resp, err = s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `account_id = "duration-filter-account" AND duration < 60000000000`,
	})
	require.NoError(t, err)
	assert.Len(t, resp.DeploymentReplicaEvents, 1)
	assert.Less(t, resp.DeploymentReplicaEvents[0].Duration.AsDuration(), time.Minute)

	// Filter by duration range (between 1 and 3 minutes)
	resp, err = s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `account_id = "duration-filter-account" AND duration >= 60000000000 AND duration <= 180000000000`,
	})
	require.NoError(t, err)
	assert.Len(t, resp.DeploymentReplicaEvents, 1)
	assert.Equal(t, 2*time.Minute, resp.DeploymentReplicaEvents[0].Duration.AsDuration())
}

