	event2 := &database.DeploymentReplicaEvent{
		DeploymentReplicaEventName: *resourcename.NewDeploymentReplicaEventName("explicit-time-account", "deployment-1", "time-event-2"),
		Type:                       gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP,
		Status:                     gpb.DeploymentReplicaEvent_FINISHED,
		Duration:                   (60 * time.Second).Nanoseconds(),
