	event3 := &database.DeploymentReplicaEvent{
		DeploymentReplicaEventName: *resourcename.NewDeploymentReplicaEventName("explicit-time-account", "deployment-1", "time-event-3"),
		Type:                       gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP,
		Status:                     gpb.DeploymentReplicaEvent_FINISHED,
		Duration:                   (90 * time.Second).Nanoseconds(),
		StartTime:                  time3,
		EndTime:                    time3.Add(90 * time.Second),
	}
	require.NoError(t, s.DB().Create(event3).Error)

	// Filter by start_time greater than 2021-01-01T00:00:00Z - should get 2 events (time2 and time3)
	resp, err := s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `account_id = "explicit-time-account" AND sta

rt_time > timestamp("2021-01-01T00:00:00Z")`,
