	resp, err = s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `account_id = "explicit-time-account" AND start_time > timestamp("2021-01-01T00:00:00Z") AND start_time < timestamp("2023-01-01T00:00:00Z")`,
	})
	require.NoError(t, err)
	assert.Len(t, resp.DeploymentReplicaEvents, 1, "Should find 1 event with start_time between 2021 and 2023")

	// Filter by end_time less than 2022-01-01 - should get 1 event: time1
	resp, err = s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter: `account_id = "explicit-time-account" AND end_time < timestamp("2022-01-01T00:00:00Z")`,
	})
