func TestListDeploymentReplicaEvents_WithOrderBy(t *testing.T) {
	s := newTestServer(t)

	// Create events with different durations
	createTestDeploymentReplicaEvent(t, s, "order-account", "order-deployment", "order-event-1",
		gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP, gpb.DeploymentReplicaEvent_FINISHED, 100*time.Second)
