		gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP, gpb.DeploymentReplicaEvent_FINISHED, 200*time.Second)

	// Order by duration ascending
	resp, err := s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
