	assert.LessOrEqual(t, resp.DeploymentReplicaEvents[1].Duration.AsDuration(), resp.DeploymentReplicaEvents[2].Duration.AsDuration())

	// Order by duration descending
	resp, err = s.ListDeploymentReplicaEvents(context.Background(), &agpb.ListDeploymentReplicaEventsRequest{
		Filter:  `account_id = "order-account"`,
		OrderBy: "duration desc",
	})
	require.NoError(t, err)
	require.Len(t, resp.DeploymentReplicaEvents, 3)
	assert.GreaterOrEqual(t, resp.DeploymentReplicaEvents[0].Duration.AsDuration(), resp

.DeploymentReplicaEvents[1].Duration.AsDuration())
	assert.GreaterOrEqual(t, resp.DeploymentReplicaEvents[1].Duration.AsDuration(), resp.DeploymentReplicaEvents[2].Duration.AsDuration())
}

