// TestGetDeploymentReplicaEventDurationDistribution_WithTimestampFilter tests that timestamp filters work correctly.
// Note: This test verifies the filter parsing works, but SQLite doesn't support percentile_cont/COUNT FILTER,
// so actual distribution calculation is only tested against PostgreSQL.
func TestGetDeploymentReplicaEventDurationDistribution_WithTimestampFilter(t *testing.T) {
	s := newTestServer(t)

	// Create test events with specific timestamps
	time1 := time.Date(2024, 1, 1, 12, 0, 0, 0, time.UTC)
	time2 := time.Date(2024, 1, 15, 12, 0, 0, 0, time.UTC)
	time3 := time.Date(2024, 2, 1, 12, 0, 0, 0, time.UTC)

	event1 := &database.DeploymentReplicaEvent{
		DeploymentReplicaEventName: *resourcename.NewDeploymentReplicaEventName("dist-time-account", "deployment-1", "dist-time-event-1"),
		Type:                       gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP,
		Status:                     gpb.DeploymentReplicaEvent_FINISHED,
		Duration:                   (2 * time.Minute).Nanoseconds(),
		StartTime:                  time1,
		EndTime:                    time1.Add(2 * time.Minute),
	}
	require.NoError(t, s.DB().Create(event1).Error)

	event2 := &database.DeploymentReplicaEvent{
		DeploymentReplicaEventName: *resourcename.NewDeploymentReplicaEventName("dist-time-account", "deployment-1", "dist-time-event-2"),
		Type:                       gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP,
		Status:                     gpb.DeploymentReplicaEvent_FINISHED,
		Duration:                   (5 * time.Minute).Nanoseconds(),
		StartTime:                  time2,
		EndTime:                    time2.Add(5 * time.Minute),
	}
	require.NoError(t, s.DB().Create(event2).Error)

	event3 := &database.DeploymentReplicaEvent{
		DeploymentReplicaEventName: *resourcename.NewDeploymentReplicaEventName("dist-time-account", "deployment-1", "dist-time-event-3"),
		Type:                       gpb.DeploymentReplicaEvent_AUTOMATIC_SCALE_UP,
		Status:                     gpb.DeploymentReplicaEvent_FINISHED,
		Duration:                   (10 * time.Minute).Nanoseconds(),
		StartTime:                  time3,
		EndTime:                    time3.Add(10 * time.Minute),
	}
	require.NoError(t, s.DB().Create(event3).Error)

	// Test with timestamp filter - this verifies the filter parsing works correctly
	// The actual distribution calculation will fail on SQLite but the filter should parse
	_, err := s.GetDeploymentReplicaEventDurationDistribution(context.Background(), &agpb.GetDeploymentReplicaEventDurationDistributionRequest{
		Filter: `account_id = "dist-time-account" AND start_time >= timestamp("2024-01-01T00:00:00Z") AND start_time <= timestamp("2024-01-31T23:59:59Z")`,
		Buckets: []*agpb.DeploymentReplicaEventDurationBucket{
			{Start: durationpb.New(0), End: durationpb.New(5 * time.Minute)},
			{Start: durationpb.New(5 * time.Minute), End: durationpb.New(15 * time.Minute)},
		},
		Percentiles: []*agpb.DeploymentReplicaEventDurationPercentile{
			{Percentile: 50},
			{Percentile: 90},
		},
	})
	// SQLite doesn't support percentile_cont/COUNT FILTER, so we expect an error in unit tests
	// In integration tests against PostgreSQL, this should succeed
	if err != nil {
		// Verify it's a SQL syntax error from SQLite, not a filter parsing error
		assert.NotContains(t, err.Error(), "invalid filter", "Filter should parse correctly, error should be from SQLite not supporting aggregate functions")
	}
}

// TestBuildPercentileQuery verifies the PostgreSQL percentile query is built correctly.
func TestBuildPercentileQuery(t *testing.T) {
	tests := []struct {
		name        string
		percentiles []*agpb.DeploymentReplicaEventDurationPercentile
		expectedSQL string
	}{
		{
			name: "single percentile p50",
			percentiles: []*agpb.DeploymentReplicaEventDurationPercentile{
				{Percentile: 50},
			},
			expectedSQL: `COALESCE(percentile_cont(ARRAY[0.5]) WITHIN GROUP (ORDER BY "Duration"), ARRAY[]::float8[])`,
		},
		{
			name: "multiple percentiles p50 p90 p99",
			percentiles: []*agpb.DeploymentReplicaEventDurationPercentile{
				{Percentile: 50},
				{Percentile: 90},
				{Percentile: 99},
			},
			expectedSQL: `COALESCE(percentile_cont(ARRAY[0.5, 0.9, 0.99]) WITHIN GROUP (ORDER BY "Duration"), ARRAY[]::float8[])`,
		},
		{
			name: "edge case p0 and p100",
			percentiles: []*agpb.DeploymentReplicaEventDurationPercentile{
				{Percentile: 0},
				{Percentile: 100},
			},
			expectedSQL: `COALESCE(percentile_cont(ARRAY[0, 1]) WITHIN GROUP (ORDER BY "Duration"), ARRAY[]::float8[])`,
		},
		{
			name: "common SLA percentiles",
			percentiles: []*agpb.DeploymentReplicaEventDurationPercentile{
				{Percentile: 50},
				{Percentile: 75},
				{Percentil

e: 90},
				{Percentile: 95},
				{Percentile: 99},
			},
			expectedSQL: `COALESCE(percentile_cont(ARRAY[0.5, 0.75, 0.9, 0.95, 0.99]) WITHIN GROUP (ORDER BY "Duration"), ARRAY[]::float8[])`,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			sql := buildPercentileQuery(tc.percentiles)
			assert.Equal(t, tc.expectedSQL, sql)
		})
	}
}

// TestBuildBucketQuery verifies the PostgreSQL bucket counting query is built correctly.
func TestBuildBucketQuery(t *testing.T) {
	tests := []struct {
		name         string
		buckets      []*agpb.DeploymentReplicaEventDurationBucket
		expectedSQL  string
		expectedArgs []interface{}
	}{
		{
			name: "single bucket",
			buckets: []*agpb.DeploymentReplicaEventDurationBucket{
				{Start: durationpb.New(0), End: durationpb.New(time.Minute)},
			},
			expectedSQL: `COUNT(*) FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ?)`,
			expectedArgs: []interface{}{int64(0), int64(60000000000), int64(0), int64(60000000000), int64(0)},
		},
		{
			name: "multiple buckets",
			buckets: []*agpb.DeploymentReplicaEventDurationBucket{
				{Start: durationpb.New(0), End: durationpb.New(time.Minute)},
				{Start: durationpb.New(time.Minute), End: durationpb.New(5 * time.Minute)},
				{Start: durationpb.New(5 * time.Minute), End: durationpb.New(10 * time.Minute)},
			},
			expectedSQL: `COUNT(*) FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ?), ` +
				`COUNT(*) FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ?), ` +
				`COUNT(*) FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ?)`,
			expectedArgs: []interface{}{
				int64(0), int64(60000000000), int64(0), int64(60000000000), int64(0),
				int64(60000000000), int64(300000000000), int64(60000000000), int64(300000000000), int64(60000000000),
				int64(300000000000), int64(600000000000), int64(300000000000), int64(600000000000), int64(300000000000),
			},
		},
		{
			name: "hour-based buckets",
			buckets: []*agpb.DeploymentReplicaEventDurationBucket{
				{Start: durationpb.New(0), End: durationpb.New(time.Hour)},
				{Start: durationpb.New(time.Hour), End: durationpb.New(24 * time.Hour)},
			},
			expectedSQL: `COUNT(*) FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ?), ` +
				`COUNT(*) FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ?)`,
			expectedArgs: []interface{}{
				int64(0), int64(3600000000000), int64(0), int64(3600000000000), int64(0),
				int64(3600000000000), int64(86400000000000), int64(3600000000000), int64(86400000000000), int64(3600000000000),
			},
		},
		{
			name: "overlapping buckets for cumulative distribution",
			buckets: []*agpb.DeploymentReplicaEventDurationBucket{
				{Start: durationpb.New(0), End: durationpb.New(time.Minute)},
				{Start: durationpb.New(0), End: durationpb.New(5 * time.Minute)},
				{Start: durationpb.New(0), End: durationpb.New(10 * time.Minute)},
			},
			expectedSQL: `COUNT(*) FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
				`COUNT(DISTINCT "DeploymentId") FILTER (WHERE "Duration" >= ? AND "Duration" < ?), ` +
