const (
	LatestVersion = "latest"
)

func (s *Server) GetDeploymentShapeVersion(ctx context.Context, r *gpb.GetDeploymentShapeVersionRequest) (*gpb.DeploymentShapeVersion, error) {
	// Parse the resource name.
	var dsvn resourcename.DeploymentShapeVersionName
	if err := dsvn.ParseFrom(r.Name); err != nil {
		return nil, err
	}

	p := auth.GetPrincipalFromCtx(ctx)
	var dbdsv database.DeploymentShapeVersion
	// Query DB to find the latest version based on create time.
	if dsvn.VersionId == LatestVersion {
		// Apply the read mask filter to the database query.
		scope, err := database.ReadMaskScope(r, (&database.DeploymentShapeVersion{}).FilterDefs())
		if err != nil {
			return nil, fmt.Errorf("error applying read mask scope: %w", err)
		}

		// Return the latest version.
		err = s.DB(ctx).Where(&database.DeploymentShapeVersion{
			DeploymentShapeVersionName: resourcename.DeploymentShapeVersionName{
				AccountId:         dsvn.AccountId,
				DeploymentShapeId: dsvn.DeploymentShapeId,
			},
		}).Order(`"CreateTime" DESC`).Scopes(deploymentshape.VisibleScope(p), scope).First(&dbdsv).Error
		if err != nil {
			return nil, err
		}

		dsv := dbdsv.ToProto()
		omitDeprecatedDeploymentShapeDraftModel(dsv)
		return dsv, nil
	}

	// TODO: Use something besides GetResource() here since this will leak information
	// about the existence of a deployment shape version before the Public check.
	// Get the deployment shape version.
	err := s.GetResource(ctx, r, &dbdsv)
	if err != nil {
		return nil, err
	}

	if !p.ActAsSuperuser() && p.User(dbdsv.AccountId) == nil && !dbdsv.Public {
		return nil, fwerror.New(gpb.Code_PERMISSION_DENIED, "")
	}

	dsv := dbdsv.ToProto()
	s.maybeHideDeploymentShapeAcceleratorCount(ctx, dsv.Snapshot, dbdsv.AccountId)
	omitDeprecatedDeploymentShapeDraftModel(dsv)
	return dsv, nil
}

func (s *Server) UpdateDeploymentShapeVersion(ctx context.Context, r *gpb.UpdateDeploymentShapeVersionRequest) (*gpb.DeploymentShapeVersion, error) {
	p := auth.GetPrincipalFromCtx(ctx)
	// Validate that latest_validated is not in the update mask
	if r.UpdateMask != nil {
		if slices.Contains(r.UpdateMask.Paths, "latest_validated") {
			return nil, fwerror.New(gpb.Code_INVALID_ARGUMENT, "latest_validated field cannot be updated directly - it's automatically managed when validated is set to true")
		}
		if slices.Contains(r.UpdateMask.Paths, "validated") && !r.DeploymentShapeVersion.Validated {
			return nil, fwerror.New(gpb.Code_INVALID_ARGUMENT, "cannot unset validated flag")
		}
		if slices.Contains(r.UpdateMask.Paths, "validated") && !p.ActAsSuperuser() {
			return nil, fwerror.New(gpb.Code_PERMISSION_DENIED, "user cannot set validated flag")
		}

	}

	maskIncludes := func(path string) bool {
		return r.UpdateMask == nil || len(r.UpdateMask.Paths) == 0 || slices.Contains(r.UpdateMask.Paths, path)
	}
	// Only allow in-place snapshot display name renames when explicitly requested via
	// the update mask (never on a legacy nil/empty mask "replace all" request), since
	// the snapshot is otherwise treated as immutable.
	isUpdatingDisplayName := r.UpdateMask != nil && slices.Contains(r.UpdateMask.Paths, "snapshot.display_name")
	if isUpdatingDisplayName && !p.ActAsSuperuser() {
		return nil, fwerror.New(gpb.Code_PERMISSION_DENIED, "only superusers can update the snapshot display name")
	}
	isUpdatingLoadTestInput := maskIncludes("load_test_input") && r.DeploymentShapeVersion.LoadTestInput != nil
	isUpdatingLoadTestOutput := maskIncludes("load_test_output") && r.DeploymentShapeVersion.LoadTestOutput != nil
	isUpdatingLoadTestSummary := maskIncludes("load_test_summary") && r.DeploymentShapeVersion.LoadTestSummary != nil
	isUpdatingEvalOutput := maskIncludes("eval_output") && r.DeploymentShapeVersion.EvalOutput != nil
	isUpdatingKldOutput := maskIncludes("kld_output") && r.DeploymentShapeVersion.KldOutput != nil
	isUpdatingFormatterTestOutput := maskIncludes("formatter_test_output") && r.DeploymentShapeVersion.FormatterTestOutput != nil

	// Permission check for load test fields
	if (isUpdatingLoadTestInput || isUpdatingLoadTestOutput || isUpdatingLoadTestSumma

ry || isUpdatingEvalOutput || isUpdatingKldOutput || isUpdatingFormatterTestOutput) && !p.ActAsSuperuser() {
		return nil, fwerror.New(gpb.Code_PERMISSION_DENIED, "only superusers can update test fields")
	}

	var dbdsv database.DeploymentShapeVersion
	err := dbdsv.PopulateFromName(s.DB(ctx), r.DeploymentShapeVersion.Name)
	if err != nil {
		return nil, fmt.Errorf("error getting deployment shape version: %w", err)
	}

	// Merge dbds into r.DeploymentShapeVersion.
	err = aip.MergeProtos(r.UpdateMask, dbdsv.ToProto(), r.DeploymentShapeVersion)
	if err != nil {
		return nil, fwerror.New(gpb.Code_INVALID_ARGUMENT, "`update` request must specify fields to be updated")
	}

	// Guarantee that following constraints for public versions are met
	if r.DeploymentShapeVersion.Public {
		// 1) Must belong to fireworks account
		if dbdsv.AccountId != constants.FireworksAccountId {
			return nil, fwerror.New(gpb.Code_PERMISSION_DENIED, "only deployment shape under fireworks account can be made public")
		}
		// 2) Must have a specified preset_type in snapshot
		if dbdsv.Snapshot.PresetType == gpb.DeploymentShape_PRESET_TYPE_UNSPECIFIED {
			return nil, fwerror.New(gpb.Code_INVALID_ARGUMENT, "public deployment shape versions must specify preset_type")
		}
		// 3) Must be validated
		if !r.DeploymentShapeVersion.Validated {
			return nil, fwerror.New(gpb.Code_INVALID_ARGUMENT, "public deployment shape versions must be validated")
		}
		// 4) If public and latest_validated, enforce uniqueness for presets by exact base_model
		// and exact accelerator_type (e.g. B200 and B300 do not conflict).
		sn := r.DeploymentShapeVersion.Snapshot
		preset := sn.PresetType

		var conflict database.DeploymentShapeVersion
		// First, check for conflict on exact base_model (when provided)
		if strings.TrimSpace(sn.BaseModel) != "" {
			exact := s.DB(ctx).
				Where(&database.DeploymentShapeVersion{Public: true, LatestValidated: true}).
				Where("\"Snapshot_BaseModel\" = ?", sn.BaseModel).
				Where("\"Snapshot_PresetType\" = ?", int32(preset)).
				Where("\"Snapshot_AcceleratorType\" = ?", int32(sn.AcceleratorType)).
				Not("\"AccountId\" = ? AND \"DeploymentShapeId\" = ?", dbdsv.AccountId, dbdsv.DeploymentShapeId)
			err := exact.First(&conflict).Error
			if err == nil {
				return nil, fwerror.New(
					gpb.Code_INVALID_ARGUMENT,
					"conflicting public latest-validated shape exists for preset_type %s with accelerator_type %s for the same base_model: %s",
					preset.String(),
					sn.AcceleratorType.String(),
					conflict.Name(),
				)
			}
			if !errors.Is(err, gorm.ErrRecordNotFound) {
				return nil, fmt.Errorf("error checking for conflicting public shapes (exact base_model): %w", err)
			}
		}
	}

	// Auto-compute load_test_summary when load_test_output is updated,
	// unless the user is explicitly setting load_test_summary themselves
	if isUpdatingLoadTestOutput && !isUpdatingLoadTestSummary {
		presetType := dbdsv.Snapshot.PresetType
		// Use the merged proto which has the load test output data
		loadTestSummary := buildLoadTestSummary(
			r.DeploymentShapeVersion.LoadTestOutput,
			presetType,
		)
		r.DeploymentShapeVersion.LoadTestSummary = loadTestSummary
	}

	var updates database.DeploymentShapeVersion
	updates.FromProto(r.DeploymentShapeVersion)

	// Execute in transaction to ensure atomicity
	err = s.DB(ctx).Transaction(func(tx *gorm.DB) error {
		// Only select fields that are safe to write. JSON-serialized fields
		// (LoadTestInput, LoadTestOutput, EvalOutput, FormatterTestOutput,
		// LoadTestSummary, KldOutput) must only be included when explicitly requested,
		// because re-serializing a round-tripped nil/empty proto through GORM
		// can produce invalid JSON for Postgres (SQLSTATE 22P02).
		mutableFields := database.GetMutableFields(&gpb.DeploymentShapeVersion{})

		jsonFields := map[string]bool{
			"LoadTestInput":       true,
			"LoadTestOutput":      true,
			"EvalOutput":          true,
			"FormatterTestOutput": true,
			"LoadTestSummary":     true,
			"KldOutput":           true,
		}
		filteredFields := make([]string, 0, len(mutableFields))
		for _, f := range mutableFields {
			if !jsonFields[f] {
				filteredFields = append(filteredFields, f)
			}
		}
		mutableFields = filteredFields

		if isUpdatingLoadTestInput {
			mutableFields = append(mutableFields, "LoadTestInput")
		}
		if isUpdatingLoadTestOutput {
			mutableFields = append(mutableFields, "LoadTestOutput")
			if !isUpdatingLoadTestSummary {
				mutableFields = append(mutableFields, "LoadTestSummary")
			}
		}
		if isUpdatingLoadTestSummary {
			mutableFields = append(mutableFields, "LoadTestSummary")
		}
		if isUpdatingEvalOutput {
			mutableFields = append(mutableFields, "EvalOutput")
		}
		if isUpdatingKldOutput {
			mutableFields = append(mutableFields, "KldOutput")
		}
		if isUpdatingFormatterTestOutput {
			mutableFields = append(mutableFields, "FormatterTestOutput")
		}
		// Snapshot fields are OUTPUT_ONLY, so GetMutableFields never includes the

m.
		// Allow the display name column to be written when explicitly requested.
		if isUpdatingDisplayName {
			mutableFields = append(mutableFields, "Snapshot_DisplayName")
		}

		result := tx.Model(&dbdsv).Select(mutableFields).Updates(updates)
		if result.Error != nil {
			return fmt.Errorf("error updating deployment shape version: %w", result.Error)
		}

		// If this update involves validation, recalculate LatestValidated for the entire shape
		if slices.Contains(r.UpdateMask.Paths, "validated") {
			err := s.UpdateLatestValidatedForShape(tx, dbdsv.AccountId, dbdsv.DeploymentShapeId)
			if err != nil {
				return fmt.Errorf("error updating latest_validated flags: %w", err)
			}
		}

		return nil
	})

	if err != nil {
		return nil, err
	}

	// Refetch to get the updated LatestValidated status
	var updatedDbdsv database.DeploymentShapeVersion
	err = updatedDbdsv.PopulateFromName(s.DB(ctx), r.DeploymentShapeVersion.Name)
	if err != nil {
		return nil, fmt.Errorf("error getting deployment shape version after update: %w", err)
	}

	dsv := updatedDbdsv.ToProto()
	s.maybeHideDeploymentShapeAcceleratorCount(ctx, dsv.Snapshot, updatedDbdsv.AccountId)
	omitDeprecatedDeploymentShapeDraftModel(dsv)
	return dsv, nil
}

func (s *Server) ListDeploymentShapeVersions(ctx context.Context, r *gpb.ListDeploymentShapeVersionsRequest) (*gpb.ListDeploymentShapeVersionsResponse, error) {
	if r.OrderBy == "" {
		r.OrderBy = "create_time desc"
	}

	p := auth.GetPrincipalFromCtx(ctx)

	var dsn resourcename.DeploymentShapeName
	var dbdsv []*database.DeploymentShapeVersion
	var response gpb.ListDeploymentShapeVersionsResponse
	err := s.ListResources(ctx, r, &dsn, &database.DeploymentShapeVersion{}, &dbdsv, &response, deploymentshape.VisibleScope(p))
	if err != nil {
		return nil, err
	}

	for i, dsv := range response.DeploymentShapeVersions {
		s.maybeHideDeploymentShapeAcceleratorCount(ctx, dsv.Snapshot, dbdsv[i].AccountId)
		omitDeprecatedDeploymentShapeDraftModel(dsv)
	}

	return &response, nil
}

func (s *Server) MatchDeploymentShapeVersions(ctx context.Context, r *gpb.MatchDeploymentShapeVersionsRequest) (*gpb.ListDeploymentShapeVersionsResponse, error) {
	createReq := r.GetCreateDeploymentRequest()
	if createReq == nil {
		return nil, fwerror.New(gpb.Code_INVALID_ARGUMENT, "create_deployment_request is required")
	}
	targetModel := createReq.GetDeployment().GetBaseModel()
	if targetModel == "" {
		return nil, fwerror.New(gpb.Code_INVALID_ARGUMENT, "create_deployment_request.deployment.base_model is required")
	}

	criteria, targetIsEmbedding, err := s.deploymentShapeVersionMatchCriteria(ctx, targetModel)
	if err != nil {
		return nil, err
	}

	scopes := []database.Scope{
		deploymentshape.VisibleScope(auth.GetPrincipalFromCtx(ctx)),
		deploymentshape.LatestValidatedScope(),
		criteria.ShapeVersionCompatScope(),
	}

	var candidates []*database.DeploymentShapeVersion
	if err := s.DB(ctx).Scopes(scopes...).Order(`"CreateTime" DESC`).Find(&candidates).Error; err != nil {
		return nil, fmt.Errorf("error matching deployment shape versions: %w", err)
	}

	matches := preferExactDeploymentShapeVersionMatches(
		s.filterDeploymentShapeVersionsByEmbeddingStatus(ctx, candidates, targetIsEmbedding),
		targetModel,
	)
	response := &gpb.ListDeploymentShapeVersionsResponse{
		DeploymentShapeVersions: make([]*gpb.DeploymentShapeVersion, 0, len(matches)),
		TotalSize:               int32(len(matches)),
	}
	for _, dbdsv := range matches {
		dsv := dbdsv.ToProto()
		s.maybeHideDeploymentShapeAcceleratorCount(ctx, dsv.Snapshot, dbdsv.AccountId)
		omitDeprecatedDeploymentShapeDraftModel(dsv)
		response.DeploymentShapeVersions = append(response.DeploymentShapeVersions, dsv)
	}
	return response, nil
}

func (s *Server) deploymentShapeVersionMatchCriteria(ctx context.Context, targetModel string) (shapeutil.ShapeMatchCriteria, bool, error) {
	target, err := s.accessibleModel(ctx, targetModel)
	if err != nil {
		return shapeutil.ShapeMatchCriteria{}, false, fmt.Errorf("error getting model: %w", err)
	}

	modelType := ""
	parameterCount := int64(0)
	if target.GetBaseModelDetails() != nil && target.GetBaseModelDetails().GetModelType() != "" && target.GetBaseModelDetails().GetParameterCount() != 0 {
		modelType = target.BaseModelDetails.ModelType
		parameterCount = target.BaseModelDetails.ParameterCount
	} else if target.Kind == gpb.Model_HF_PEFT_ADDON || target.Kind == gpb.Model_LIVE_MERGE {
		if target.GetPeftDetails() == nil || target.GetPeftDetails().GetBaseModel() == "" {
			return shapeutil.ShapeMatchCriteria{}, false, fwerror.New(gpb.Code_FAILED_PRECONDITION, "missing base model details")
		}
		base, err := s.accessibleModel(ctx, target.PeftDetails.BaseModel)
		if err != nil {
			return shapeutil.ShapeMatchCriteria{}, false, fmt.Errorf("error getting base model: %w", err)
		}
		if base.GetBaseModelDetails() == nil || base.GetBaseModelDetails().GetParameterCount() == 0 {
			return shapeutil.ShapeMatchCriteria{}, false, fwerror.New(gpb.Code_FAILED_PRE

CONDITION, "missing base model details")
		}
		parameterCount = base.BaseModelDetails.ParameterCount
		if target.GetPeftDetails().GetBaseModelType() != "" {
			modelType = target.GetPeftDetails().GetBaseModelType()
		} else {
			modelType = base.GetBaseModelDetails().GetModelType()
		}
	}
	if modelType == "" || parameterCount == 0 {
		return shapeutil.ShapeMatchCriteria{}, false, fwerror.New(gpb.Code_FAILED_PRECONDITION, "missing base model details")
	}
	return shapeutil.NewShapeMatchCriteria(target.GetName(), modelType, parameterCount), target.GetKind() == gpb.Model_EMBEDDING_MODEL, nil
}

func (s *Server) accessibleModel(ctx context.Context, name string) (*gpb.Model, error) {
	var model database.Model
	if err := model.PopulateFromName(s.DB(ctx), name); err != nil {
		return nil, err
	}
	if err := modelpkg.ValidateModelReferenceAccess(ctx, &model); err != nil {
		return nil, err
	}
	return model.ToProto(), nil
}

func (s *Server) filterDeploymentShapeVersionsByEmbeddingStatus(ctx context.Context, shapes []*database.DeploymentShapeVersion, targetIsEmbedding bool) []*database.DeploymentShapeVersion {
	filtered := make([]*database.DeploymentShapeVersion, 0, len(shapes))
	for _, shape := range shapes {
		if shape.Snapshot == nil {
			continue
		}
		shapeBase, err := s.accessibleModel(ctx, shape.Snapshot.BaseModel)
		if err != nil {
			continue
		}
		if (shapeBase.GetKind() == gpb.Model_EMBEDDING_MODEL) == targetIsEmbedding {
			filtered = append(filtered, shape)
		}
	}
	return filtered
}

func preferExactDeploymentShapeVersionMatches(shapes []*database.DeploymentShapeVersion, targetModel string) []*database.DeploymentShapeVersion {
	exact := make([]*database.DeploymentShapeVersion, 0, len(shapes))
	for _, shape := range shapes {
		if shape.Snapshot == nil {
			continue
		}
		if shape.Snapshot.BaseModel == targetModel {
			exact = append(exact, shape)
		}
	}
	if len(exact) > 0 {
		return exact
	}
	return shapes
}

func omitDeprecatedDeploymentShapeDraftModel(dsv *gpb.DeploymentShapeVersion) {
	if dsv == nil || dsv.Snapshot == nil {
		return
	}
	dsv.Snapshot.DraftModel = ""
}

// UpdateLatestValidatedForShape sets LatestValidated based on create_time desc for validated versions
func (s *Server) UpdateLatestValidatedForShape(tx *gorm.DB, accountId, deploymentShapeId string) error {
	// Step 1: Clear the LatestValidated flag for this shape
	clearResult := tx.Model(&database.DeploymentShapeVersion{}).
		Where(&database.DeploymentShapeVersion{
			DeploymentShapeVersionName: resourcename.DeploymentShapeVersionName{
				AccountId:         accountId,
				DeploymentShapeId: deploymentShapeId,
			},
			Validated:       true,
			LatestValidated: true,
		}).
		Update("LatestValidated", false)
	if clearResult.Error != nil {
		return clearResult.Error
	}

	// Step 2: Find the most recent validated version
	var latestValidatedVersion database.DeploymentShapeVersion
	result := tx.Where(&database.DeploymentShapeVersion{
		DeploymentShapeVersionName: resourcename.DeploymentShapeVersionName{
			AccountId:         accountId,
			DeploymentShapeId: deploymentShapeId,
		},
		Validated: true,
	}).
		Order(`"CreateTime" DESC`).
		First(&latestValidatedVersion)

	if result.Error != nil {
		return result.Error
	}

	// Step 3: Set LatestValidated on the found version
	updateResult := tx.Model(&latestValidatedVersion).Update("LatestValidated", true)
	return updateResult.Error
}

