func rlorTrainerPlacementKind(rlorJobType gpb.RlorJobType, enableKeepAlive bool) dwpb.TrainerPlacementSubject_Kind {
	if enableKeepAlive {
		return dwpb.TrainerPlacementSubject_RFT_KEEP_ALIVE
	}
	switch rlorJobType {
	case gpb.RlorJobType_DPO, gpb.RlorJobType_ORPO:
