		jobBuilder = jobBuilder.WithReferenceModelAddon(a.runtime.GetDatabase(), input.ReferenceModelAddon)
	}

	if trainingConfig.WarmStartFrom != "" {
		jobBuilder = jobBuilder.WithInputPeftAddon(a.runtime.GetDatabase(), trainingConfig.WarmStartFrom)
	}

	if trainingConfig.LearningRate != 0 {
		jobBuilder = jobBuilder.WithLearningRate(trainingConfig.LearningRate)
	}

	if trainingConfig.MaxContextLength != 0 {
		jobBuilder = jobBuilder.WithMaxContextLength(trainingConfig.MaxContextLength)
	}

	if trainingConfig.BatchSize != 0 {
		jobBuilder = jobBuilder.WithBatchSize(trainingConfig.BatchSize)
	}

	if trainingConfig.BatchSizeSamples != 0 {
		jobBuilder = jobBuilder.WithBatchSizeSamples(trainingConfig.BatchSizeSamples)
	}

	jobBuilder = jobBuilder.WithLoraRank(trainingConfig.LoraRank)
	if trainingConfig.LoraAlpha > 0 {
		jobBuilder = jobBuilder.WithLoraAlpha(trainingConfig.LoraAlpha)
	}
	if trainingConfig.LoraDropout > 0 {
		jobBuilder = jobBuilder.WithLoraDropout(trainingConfig.LoraDropout)
	}
	if len(trainingConfig.LoraTargetModules) > 0 {
		jobBuilder = jobBuilder.WithLoraTargetModules(trainingConfig.LoraTargetModules)
	}

	if trainingConfig.BaseModelWeightPrecision != gpb.WeightPrecision_WEIGHT_PRECISION_UNSPECIFIED {
		jobBuilder = jobBuilder.WithBaseModelWeightPrecision(trainingConfig.BaseModelWeightPrecision)
	}

	if trainingConfig.OptimizerWeightDecay != 0 {
		jobBuilder = jobBuilder.WithOptimizerWeightDecay(trainingConfig.OptimizerWeightDecay)
	}

	if trainingConfig.Epochs != 0 {
		jobBuilder = jobBuilder.WithEpochsCount(trainingConfig.Epochs)
	}

	if trainingConfig.GradientAccumulationSteps > 1 {
		jobBuilder = jobBuilder.WithGradientAccumulationSteps(trainingConfig.GradientAccumulationSteps)
	}

	if trainingConfig.LearningRateWarmupSteps > 0 {
		jobBuilder = jobBuilder.WithLearningRateWarmupSteps(trainingConfig.LearningRateWarmupSteps)
	}

	s3ModelCache, err := a.runtime.GetModelCacheUrlForRegion(region)

	if err != nil {
		// Model cache configuration errors are not retryable
		return nil, temporal.NewNonRetryableApplicationError(
			"Model cache not available for selected region",
			common.ErrorTypeConfigInvalid,
			err,
		)
	}

	jobBuilder = jobBuilder.WithS3RemoteCache(s3ModelCache)

	if input.Debug {
		jobBuilder = jobBuilder.WithDebug(true)
	}

	// Only set dataset and output model if not in keep-alive mode
	if !input.EnableKeepAlive {
		// Determine if this is the final model (not intermediate)
		// Final models are pre-created in the gateway, intermediate models are created on-the-fly
		isFinalModel := !trainingConfig.IsIntermediate
		jobBuilder = jobBuilder.WithTrainingDatasetPath(trainingDatasetPath)
		jobBuilder = jobBuilder.WithOutputModel(a.runtime.GetDatabase(), trainingConfig.OutputModel, &createdModel, isFinalModel)
	} else {
		jobBuilder = jobBuilder.WithKeepAlive(true)
		if input.JobTimeout != nil {
			jobBuilder = jobBuilder.WithJobTimeout(*input.JobTimeout)
		}
		// Set rollout deployment name and FIREWORKS_API_KEY secret if provided for hot reload trigger
		if input.RolloutDeploymentName != "" {
			jobBuilder = jobBuilder.WithRolloutDeploymentName(input.RolloutDeploymentName)
		}
	}

	if input.WandbConfig != nil && input.WandbConfig.Enabled && input.WandbConfig.Project != "" && input.WandbConfig.Entity != "" && input.WandbConfig.ApiKey != "" {
		jobBuilder = jobBuilder.WithWandbConfig(input.WandbConfig)
	}

	// multi node setup
	if input.TrainingNodeCount > 1 {
		boostedLearningRate := trainingConfig.LearningRate * float32(math.Sqrt(float64(input.TrainingNodeCount)))
		jobBuilder = jobBuilder.WithLearningRate(boostedLearningRate)
	}

	if input.TrainingConfig != nil {
		// Filter --profile from extra args (it's a control-plane-only flag, not forwarded to trainer)
		filteredExtraArgs, hasProfile := rlor_trainer_job.FilterProfileFlag(input.TrainingConfig.ExtraArgs)

		// Generate profile directory for full-parameter (firetitan) jobs only when --profile is passed
		if trainingConfig.LoraRank == 0 && hasProfile {
			profileDir := fmt.Sprintf("gs://%s/rlor-%s-%s/profiles",
				rlorProfileBucket, input.AccountId, input.JobId)
			jobBuilder = jobBuilder.WithProfileDir(&profileDir)
		}

		extraArgs := rlor_trainer_job.WithReinforcementLearningLossConfigExtraArgs(filteredExtraArgs, input.LossConfig)
		if len(extraArgs) > 0 {
			jobBuilder = jobBuilder.WithExtraArgs(extraArgs)
		}
	}

	job, err := jobBuilder.Build()

	if err != nil {
		// Job configuration errors are not retryable
		return nil, temporal.NewNonRetryableApplicationError(
			"Failed to build training job configuration",
			common.ErrorTypeConfigInvalid,
			err,
		)
	}

	// create headless ser

vice for distributed training first if needed
	// note: this needs to be always go before the job creation
	headlessServiceName := ""
	if input.TrainingNodeCount > 1 {
		headlessServiceName, err = a.createHeadlessServiceForDistributedTraining(ctx, k8sClient, job.Name, lros.JobFamily)
		if err != nil {
			return nil, fmt.Errorf("error creating headless service for distributed training: %w", err)
		}
	}

	// Create the K8s job
	logger.Info("Creating Kubernetes job", "k8s_job_name", job.Name)
	k8sJob, err := utils.CreateK8sJobWithRetry(ctx, k8sClient, jobNamespace, job, k8sRetryCount, metav1.CreateOptions{})
	if err != nil {
		return nil, fmt.Errorf("error creating Kubernetes job %s: %w", job.Name, err)
	}

	// K8s job submitted: best-effort commit so capacity is reflected by
	// real running pods. Failures absorbed by the orphan sweeper.
	lros.CommitTrainerJob(ctx, a.runtime, placement, subjectName)

	// TODO: update k8s name in heartbeat?
	// Return consistent timeout response when loop completes
	return &RunCreateRlorK8sOutput{
		K8sJobName:                    k8sJob.Name,
		Region:                        region,
		JobStatusFile:                 jobStatusFile,
		JobBillingFile:                jobBillingFile,
		JobMetricsFile:                jobMetricsFile,
		TrainerLogsFile:               trainerLogsFile,
		ModelCheckpointDirectory:      modelCheckpointDirectory,
		DcpCheckpointDirectory:        dcpCheckpointDirectory,
		CreateTime:                    time.Now(),
		HeadlessServiceName:           headlessServiceName,
		TrainerPlacementSubject:       trainerPlacementSubject,
		TrainerPlacementReservationID: trainerReservationID,
	}, nil
}

// createHeadlessServiceForDistributedTraining creates a headless service for multi-node distributed training
func (a *RlorTrainerActivity) createHeadlessServiceForDistributedTraining(ctx context.Context, k8sClient kubernetes.Interface, jobName, namespace string) (string, error) {
	serviceName := fmt.Sprintf("%s-headless", jobName)

	// Check if service already exists (idempotent operation)
	_, err := k8sClient.CoreV1().Services(namespace).Get(ctx, serviceName, metav1.GetOptions{})
	if err == nil {
		// Service already exists, no need to create
		return serviceName, nil
	}

	// Create a headless service for the distributed job
	headlessService := &corev1.Service{
		ObjectMeta: metav1.ObjectMeta{
			Name:      serviceName,
			Namespace: namespace,
			Labels: map[string]string{
				"app.kubernetes.io/name":    "rlor-trainer",
				"app.kubernetes.io/part-of": "training",
				"dist-training-job":         jobName,
			},
		},
		Spec: corev1.ServiceSpec{
			ClusterIP: "None", // Headless service
			Selector: map[string]string{
				"app.kubernetes.io/name":       "rlor-trainer",
				"dist-training-job":            jobName,
				"batch.kubernetes.io/job-name": jobName,
			},
			Ports: []corev1.ServicePort{
				{
					Port:       29500,
					TargetPort: intstr.FromInt(29500),
				},
			},
		},
	}

	_, err = k8sClient.CoreV1().Services(namespace).Create(ctx, headlessService, metav1.CreateOptions{})
	// Ignore AlreadyExists errors (race condition)
	if err != nil && !apierrors.IsAlreadyExists(err) {
		return "", fmt.Errorf("failed to create headless service: %w", err)
	}

	return serviceName, nil
}

type RunUpdateRlorModelInput struct {
	TrainingConfig *gpb.BaseTrainingConfig
}

type RunUpdateRlorModelOutput struct {
	BaseModel database.Model
}

// Updates the RLOR model in DB
func (a *RlorTrainerActivity) RunUpdateRlorModel(ctx context.Context, input RunUpdateRlorModelInput) (*RunUpdateRlorModelOutput, error) {
	// TODO: include completion time in heartbeat
	err := updateFineTunedModel(ctx, input.TrainingConfig, a.runtime)
	if err != nil {
		return nil, fmt.Errorf("error creating fine-tuned model: %w", err)
	}
	db := a.runtime.GetDatabase()
	var baseModelName resourcename.ModelName
	var baseModel database.Model
	// Handle the case where the base model is a warm start model
	if input.TrainingConfig.BaseModel == "" {
		var warmStartModel database.Model
		err = warmStartModel.PopulateFromName(db, input.TrainingConfig.WarmStartFrom)
		if err != nil {
			// Model not found won't be fixed by retrying
			return nil, temporal.NewNonRetryableApplicationError(
				fmt.Sprintf("Warm start model %s not found", input.TrainingConfig.WarmStartFrom),
				common.ErrorTypeResourceNotFound,
				err,
			)
		}
		err = baseModelName.ParseFrom(warmStartModel.PeftDetails.BaseModel)
		if err != nil {
			// Parse error is a configuration issue - not retryable
			return nil, temporal.NewNonRetryableApplicationError(
				"Invalid warm start model configuration",
				common.ErrorTypeResourceInvalid,
				err,
			)
		}
	} else {
		err = baseModelName.ParseFrom(input.TrainingConfig.BaseModel)
		if err != nil {
			// Configuration error - not retryable
			return nil, temporal.NewNonRetryableApplicationError(
				fmt.Sprintf("Invalid base model name: %s", input.TrainingConfig.BaseModel),
				common.ErrorTypeResourceInva

lid,
				err,
			)
		}
	}

	err = baseModel.PopulateFromName(db, baseModelName.String())
	if err != nil {
		// Base model not found - not retryable
		return nil, temporal.NewNonRetryableApplicationError(
			fmt.Sprintf("Base model %s not found", baseModelName.String()),
			common.ErrorTypeResourceNotFound,
			err,
		)
	}
	return &RunUpdateRlorModelOutput{
		BaseModel: baseModel,
	}, nil
}

// updateFineTunedModel updates the fine-tuned model with adapter config
func updateFineTunedModel(ctx context.Context, trainingConfig *gpb.BaseTrainingConfig, runtime statemachine.Runtime) error {
	var mn resourcename.ModelName
	err := mn.ParseFrom(trainingConfig.OutputModel)
	if err != nil {
		// User error - model resource is invalid (user can fix by providing valid model name)
		return temporal.NewNonRetryableApplicationError(
			"Invalid output model name format",
			common.ErrorTypeResourceInvalid,
			err,
		)
	}
	var createdModel database.Model
	err = createdModel.Populate(runtime.GetDatabase(), &mn)
	if err != nil {
		// Model should exist at this point - if not, it's a data consistency issue
		return temporal.NewNonRetryableApplicationError(
			"Output model not found in database",
			common.ErrorTypeInternalResourceNotFound,
			err,
		)
	}

	adapterConfig, err := readAdapterConfig(ctx, createdModel.GcsUri, runtime.GetGCS())
	if err != nil {
		// Adapter config is required - if missing/invalid, job output is corrupted
		// Passing the error as-is to preserve error type (fwerror.Error or ApplicationError)
		return err
	}

	createdModel.PeftDetails.R = adapterConfig.R
	createdModel.PeftDetails.TargetModules = adapterConfig.TargetModules
	createdModel.State = gpb.Model_READY
	if createdModel.PeftDetails != nil && createdModel.PeftDetails.BaseModel != "" {
		if err := modelpkg.PropagateTunableFlagsFromBaseModel(ctx, runtime.GetDatabase(), &createdModel, createdModel.PeftDetails.BaseModel); err != nil {
			return fmt.Errorf("failed to propagate tunable flags from base model: %w", err)
		}
	}

	if err := runtime.GetDatabase().Save(&createdModel).Error; err != nil {
		return fmt.Errorf("error saving created model: %w", err)
	}
	return nil
}

// AdapterConfig contains a subset of the fields of adapter_config.json.
type AdapterConfig struct {
	R             int32    `json:"r"`
	TargetModules []string `json:"target_modules"`
}

// readAdapterConfig reads a AdapterConfig from a checkpoint directory
// containing a fireworks.json file.
func readAdapterConfig(ctx context.Context, checkpointGcsDir string, gcpClient gcp.GCSClient) (*AdapterConfig, error) {
	checkpointURL, err := url.Parse(checkpointGcsDir)
	if err != nil {
		// URL format error - won't be fixed by retrying
		return nil, temporal.NewNonRetryableApplicationError(
			"Invalid checkpoint directory URL format",
			common.ErrorTypeConfigInvalid,
			err,
		)
	}

	c := AdapterConfig{}
	data, err := gcpClient.ReadGcsFile(ctx, checkpointURL.JoinPath("adapter_config.json"))
	if err != nil {
		// File read could be transient (network) or permanent (file missing)
		// Keep as retryable for now since GCS reads can have transient failures
		return nil, fmt.Errorf("error reading adapter_config.json for PEFT config: %w", err)
	}
	err = json.Unmarshal(data, &c)
	if err != nil {
		// JSON format error - file is corrupted, won't be fixed by retrying
		return nil, temporal.NewNonRetryableApplicationError(
			"Invalid adapter_config.json format",
			common.ErrorTypeFormatInvalid,
			err,
		)
	}
	return &c, nil
}

func (a *RlorTrainerActivity) loadDatasetMetadata(ctx context.Context, datasetName string) (*database.Dataset, error) {
	var dataset database.Dataset
	if err := dataset.PopulateFromName(a.db.WithContext(ctx), datasetName); err != nil {
		return nil, temporal.NewNonRetryableApplicationError(
			fmt.Sprintf("Failed to resolve dataset %s", datasetName),
			common.ErrorTypeInternalResourceNotFound,
			err,
		)
	}
	return &dataset, nil
}

func (a *RlorTrainerActivity) resolveBaseModel(ctx context.Context, trainingConfig *gpb.BaseTrainingConfig, jobName string) (*database.Model, error) {
	if trainingConfig == nil {
		return nil, temporal.NewNonRetryableApplicationError(
			"Base model configuration is required",
			common.ErrorTypeInvalidInput,
			fmt.Errorf("training config missing for job %s", jobName),
		)
	}

	baseModelName := trainingConfig.BaseModel
	if baseModelName == "" && trainingConfig.WarmStartFrom != "" {
		var warmStart database.Model
		if err := warmStart.PopulateFromName(a.db.WithContext(ctx), trainingConfig.WarmStartFrom); err != nil {
			return nil, temporal.NewNonRetryableApplicationError(
				fmt.Sprintf("Failed to load warm start model %s", trainingConfig.WarmStartFrom),
				common.ErrorTypeInternalResourceNotFound,
				err,
			)
		}
		if warmStart.PeftDetails == nil || warmStart.PeftDetails.BaseModel == "" {
			return nil, temporal.NewNonRetryableApplicationError(
				"Warm start model is missing base model reference",
				common.ErrorTypeInvalidInput,
				f

mt.Errorf("warm start model %s missing base model", trainingConfig.WarmStartFrom),
			)
		}
		baseModelName = warmStart.PeftDetails.BaseModel
	}

	if baseModelName == "" {
		return nil, temporal.NewNonRetryableApplicationError(
			"Base model configuration is required",
			common.ErrorTypeInvalidInput,
			fmt.Errorf("no base model configured for job %s", jobName),
		)
	}

	var baseModel database.Model
	if err := baseModel.PopulateFromName(a.db.WithContext(ctx), baseModelName); err != nil {
		return nil, temporal.NewNonRetryableApplicationError(
			fmt.Sprintf("Failed to load base model %s", baseModelName),
			common.ErrorTypeInternalResourceNotFound,
			err,
		)
	}
	return &baseModel, nil
}

// Helper function to properly extract directory from GCS URLs
func getGCSDirectory(gcsPath string) string {
	lastSlash := strings.LastIndex(gcsPath, "/")
	if lastSlash == -1 {
		return gcsPath
	}
	return gcsPath[:lastSlash]
}

// EnsureRlorModelInput contains the input for EnsureRlorModel activity
type EnsureRlorModelInput struct {
	AccountID       string
	OutputModelName string
	TrainingConfig  *gpb.BaseTrainingConfig
	CreatedBy       string
	JobID           string
	// TrainerJobId is set for keepalive mode to group models under the trainer job folder
	// Path: gs://{bucket}/rlor/{trainerJobId}/{modelId}/checkpoint
	TrainerJobId string
	// RFTJobId is set for RFT mode to group models under the parent RFT job folder
	// Path: gs://{bucket}/rlor/{rftJobId}/{modelId}/checkpoint
	// Note: The modelId already contains epoch/chunk info (e.g., {jobId}-epoch-{N}-chunk-{M})
	RFTJobId string
}

// EnsureRlorModelOutput contains the output of EnsureRlorModel activity
type EnsureRlorModelOutput struct {
	ModelGcsUri string
}

// EnsureRlorModel ensures the output model entry exists in the database
func (a *RlorTrainerActivity) EnsureRlorModel(ctx context.Context, input EnsureRlorModelInput) (*EnsureRlorModelOutput, error) {
	logger := sdklog.With(activity.GetLogger(ctx), "accountId", input.AccountID, "jobId", input.JobID)
	logger.Info("Ensuring output model entry", "modelName", input.OutputModelName)

	var mn resourcename.ModelName
	if err := mn.ParseFrom(input.OutputModelName); err != nil {
		return nil, temporal.NewNonRetryableApplicationError(
			"Invalid output model name format",
			common.ErrorTypeResourceInvalid,
			err,
		)
	}

	var model database.Model
	if err := model.Populate(a.db.WithContext(ctx), &mn); err != nil {
		logger.Info("Creating new model DB entry", "modelName", input.OutputModelName)

		var account database.Account
		if err := account.Populate(a.db.WithContext(ctx), resourcename.NewAccountName(mn.AccountId)); err != nil {
			return nil, fmt.Errorf("failed to get account %s: %w", mn.AccountId, err)
		}

		baseModel, err := a.resolveBaseModel(ctx, input.TrainingConfig, input.JobID)
		if err != nil {
			return nil, err
		}

		// Construct GCS URI based on mode (unified pattern):
		// - Keepalive mode (TrainerJobId set): gs://{bucket}/rlor/{trainerJobId}/{modelId}/checkpoint
		// - RFT mode (RFTJobId set): gs://{bucket}/rlor/{rftJobId}/{modelId}/checkpoint
		//   (modelId already contains epoch/chunk info, e.g., {jobId}-epoch-{N}-chunk-{M})
		// - Legacy mode (neither set): gs://{bucket}/rlor-{jobId}/{salt}/{modelId}/checkpoint
		if input.TrainerJobId != "" {
			// Keepalive mode: group by trainer job ID
			model.GcsUri = fmt.Sprintf("gs://%s/rlor/%s/%s/checkpoint",
				account.ModelBucket, input.TrainerJobId, mn.ModelId)
		} else if input.RFTJobId != "" {
			// RFT mode: group by parent RFT job ID
			model.GcsUri = fmt.Sprintf("gs://%s/rlor/%s/%s/checkpoint",
				account.ModelBucket, input.RFTJobId, mn.ModelId)
		} else {
			// Legacy mode: keep old behavior for backward compatibility
			gcsPrefix := path.Join(account.ModelBucket, fmt.Sprintf("rlor-%s", input.JobID))
			salt := strings.ReplaceAll(uuid.New().String(), "-", "")[0:6]
			model.GcsUri = fmt.Sprintf("gs://%s/%s/%s/checkpoint", gcsPrefix, salt, mn.ModelId)
		}

		model.ModelId = mn.ModelId
		model.AccountId = mn.AccountId
		model.DisplayName = mn.ModelId
		model.CreatedBy = input.CreatedBy
		model.State = gpb.Model_UPLOADING
		model.Kind = gpb.Model_HF_PEFT_ADDON
		model.Tunable = false
		model.FineTuningJob = fmt.Sprintf("accounts/%s/reinforcementFineTuningJobs/%s", mn.AccountId, input.JobID)
		model.PeftDetails = &database.PEFTDetails{BaseModel: baseModel.ModelName.String()}
		model.DisableModelDownload = true
		if input.TrainingConfig != nil && input.TrainingConfig.GetIsIntermediate() {
			model.IsInternal = true
		}
		if baseModel.BaseModelDetails != nil {
			model.PeftDetails.BaseModelType = baseModel.BaseModelDetails.ModelType
		}
		model.BaseModelDetails = &database.BaseModelDetails{CheckpointFormat: gpb.BaseModelDetails_HUGGINGFACE}

		if err := a.db.WithContext(ctx).Create(&model).Error; err != nil {
			return nil, fmt.Errorf("failed to create model %s: %w", input.OutputModelName, err)
		}

		logger.Info("Created model entry", "gcsUri", mod

el.GcsUri)
	} else {
		logger.Info("Model already exists, returning existing GCS URI", "modelName", input.OutputModelName, "gcsUri", model.GcsUri)
	}

	return &EnsureRlorModelOutput{
		ModelGcsUri: model.GcsUri,
	}, nil
}

// CreateSynFileInput contains the input for CreateSynFile activity
type CreateSynFileInput struct {
	SessionStatusFile string // Pre-generated session status file path
	DatasetGcsUri     string
	OutputModelGcsUri string
}

// CreateSynFileOutput contains the output of CreateSynFile activity
type CreateSynFileOutput struct {
	AckFileLocation string
}

// CreateSynFile creates the syn.json file to signal the keep-alive job to start training
func (a *RlorTrainerActivity) CreateSynFile(ctx context.Context, input CreateSynFileInput) (*CreateSynFileOutput, error) {
	logger := sdklog.With(activity.GetLogger(ctx))
	logger.Info("Creating syn.json file",
		"dataset", input.DatasetGcsUri,
		"outputModel", input.OutputModelGcsUri,
		"sessionStatusFile", input.SessionStatusFile)

	signalingDir := getGCSDirectory(input.SessionStatusFile)
	synPath := fmt.Sprintf("%s/syn.json", signalingDir)

	payload := map[string]string{
		"dataset_uri":         input.DatasetGcsUri,
		"output_location":     input.OutputModelGcsUri,
		"session_status_file": input.SessionStatusFile,
	}

	body, err := json.Marshal(payload)
	if err != nil {
		return nil, temporal.NewNonRetryableApplicationError(
			"Failed to marshal syn.json",
			common.ErrorTypeFormatInvalid,
			err,
		)
	}

	synURL, err := url.Parse(synPath)
	if err != nil {
		return nil, temporal.NewNonRetryableApplicationError(
			"Invalid syn.json path format",
			common.ErrorTypeConfigInvalid,
			err,
		)
	}

	if err := a.runtime.GetGCS().WriteGcsFile(ctx, synURL, body); err != nil {
		return nil, fmt.Errorf("failed to write syn.json to %s: %w", synPath, err)
	}

	logger.Info("Created syn.json", "path", synPath)

	ackPath := fmt.Sprintf("%s/ack.json", signalingDir)
	return &CreateSynFileOutput{
		AckFileLocation: ackPath,
	}, nil
}

// PollAckAndK8sJobInput contains the input for PollAckAndK8sJob activity
type PollAckAndK8sJobInput struct {
	K8sJobName        string
	Namespace         string
	Region            gpb.Region
	SessionStatusFile string // Session-level status file for progress and errors
	AckFileLocation   string
	ExpectedDataset   string
	ExpectedOutput    string
	PollInterval      time.Duration
	MaxDuration       time.Duration
}

// PollAckAndK8sJobOutput contains the output of PollAckAndK8sJob activity
type PollAckAndK8sJobOutput struct {
	Completed    bool
	K8sJobState  gpb.JobState
	K8sJobStatus *gpb.Status
}

// PollAckAndK8sJob polls both ack.json for training completion and K8s job for failures.
// When K8s job fails, it reads the status file to get detailed error info and returns
// a typed NonRetryableApplicationError for proper error propagation.
func (a *RlorTrainerActivity) PollAckAndK8sJob(ctx context.Context, input PollAckAndK8sJobInput) (*PollAckAndK8sJobOutput, error) {
	logger := sdklog.With(activity.GetLogger(ctx),
		"k8sJobName", input.K8sJobName,
		"namespace", input.Namespace)
	logger.Info("Polling for ack.json and K8s job status")

	ackURL, err := url.Parse(input.AckFileLocation)
	if err != nil {
		return nil, temporal.NewNonRetryableApplicationError(
			"Invalid ack.json path format",
			common.ErrorTypeConfigInvalid,
			err,
		)
	}

	// Get K8s client
	k8sClient, err := a.runtime.GetK8sForRegion(input.Region)
	if err != nil {
		return nil, fmt.Errorf("error getting kubernetes client: %w", err)
	}

	deadline := time.Now().Add(input.MaxDuration)
	pollInterval := input.PollInterval
	if pollInterval == 0 {
		pollInterval = 30 * time.Second
	}

	pollTicker := time.NewTicker(pollInterval)
	defer pollTicker.Stop()

	for {
		select {
		case <-ctx.Done():
			if errors.Is(ctx.Err(), context.Canceled) {
				return nil, temporal.NewCanceledError()
			}
			return nil, ctx.Err()

		case <-pollTicker.C:
			// Check timeout - likely due to insufficient capacity (pod unschedulable)
			if time.Now().After(deadline) {
				return nil, temporal.NewNonRetryableApplicationError(
					fmt.Sprintf("polling timeout after %v, likely due to insufficient capacity", input.MaxDuration),
					common.ErrorTypeInsufficientCapacity,
					nil,
				)
			}

			// Read session status file for progress and send structured heartbeat
			if input.SessionStatusFile != "" {
				status, progress, statusErr := statemachine.GetJobStatusAndProgress(ctx, input.SessionStatusFile, a.runtime.GetGCS())
				if statusErr == nil {
					heartbeat := map[string]interface{}{
						"state":        int32(gpb.JobState_JOB_STATE_RUNNING),
						"region":       input.Region.String(),
						"job_progress": progress,
					}
					if status != nil && status.Message != "" {
						heartbeat["status_message"] = status.Message
						if status.Code != gpb.Code_OK {
							heartbeat["is_error"] = true
						}
					}
					activity.RecordHeartbeat(ctx, heartbeat)
				} else {
					// Fallback heartbeat if

 status file not ready yet
					activity.RecordHeartbeat(ctx, "Waiting for training completion")
				}
			} else {
				activity.RecordHeartbeat(ctx, "Waiting for training completion")
			}

			// Check K8s job status
			k8sJob, err := k8sClient.BatchV1().Jobs(input.Namespace).Get(ctx, input.K8sJobName, metav1.GetOptions{})
			if err != nil {
				logger.Warn("Failed to get K8s job status", "error", err)
			} else {
				// Check for job failure
				for _, condition := range k8sJob.Status.Conditions {
					if condition.Status == corev1.ConditionTrue && condition.Type == batchv1.JobFailed {
						logger.Error("K8s job failed", "reason", condition.Reason, "message", condition.Message)

						// Read session status file for error details
						if input.SessionStatusFile != "" {
							status, _, statusErr := statemachine.GetJobStatusAndProgress(ctx, input.SessionStatusFile, a.runtime.GetGCS())
							if statusErr == nil && status != nil && status.Code != gpb.Code_OK {
								logger.Info("Got error from session status file",
									"statusCode", status.Code.String(),
									"statusMessage", status.Message)

								errorType := common.MapGpbCodeToErrorType(status.Code)
								return nil, temporal.NewNonRetryableApplicationError(
									fmt.Sprintf("Training job failed: %s", status.Message),
									errorType,
									nil,
								)
							}
							// If status exists but Code is OK, it's stale progress - ignore it
							if statusErr == nil && status != nil && status.Code == gpb.Code_OK {
								logger.Info("Job failed but status file has OK code - ignoring stale progress",
									"staleMessage", status.Message)
							}
						}

						// Fallback: K8s condition message
						return nil, temporal.NewNonRetryableApplicationError(
							fmt.Sprintf("K8s job failed: %s", condition.Message),
							common.ErrorTypePrerequisiteNotMet,
							nil,
						)
					}
					if condition.Status == corev1.ConditionTrue && condition.Type == batchv1.JobComplete {
						logger.Warn("K8s job completed without ack.json - unexpected state")
						return nil, temporal.NewNonRetryableApplicationError(
							"K8s job completed but no ack.json found",
							common.ErrorTypePrerequisiteNotMet,
							nil,
						)
					}
				}
			}

			// Check ack.json
			ackContent, err := a.runtime.GetGCS().ReadGcsFile(ctx, ackURL)
			if err != nil {
				logger.Debug("ack.json not yet available, continuing to wait")
				continue
			}

			var ackData map[string]interface{}
			if err := json.Unmarshal(ackContent, &ackData); err != nil {
				logger.Warn("Failed to parse ack.json, continuing to wait", "error", err)
				continue
			}

			// Validate ack.json matches expected dataset/output
			ackDataset, _ := ackData["dataset_uri"].(string)
			ackOutput, _ := ackData["output_location"].(string)
			if ackDataset != input.ExpectedDataset || ackOutput != input.ExpectedOutput {
				logger.Info("Ignoring ack.json for previous dataset",
					"ackDataset", ackDataset,
					"expectedDataset", input.ExpectedDataset,
					"ackOutput", ackOutput,
					"expectedOutput", input.ExpectedOutput)
				continue
			}

			// Check if training is complete
			if trainingComplete, ok := ackData["training_complete"].(bool); ok && trainingComplete {
				logger.Info("Training completed successfully")
				return &PollAckAndK8sJobOutput{
					Completed:   true,
					K8sJobState: gpb.JobState_JOB_STATE_RUNNING,
				}, nil
			}
		}
	}
}

