// Start starts the worker
func (w *LROWorker) Start(ctx context.Context) error {
	log.Info().
		Str("task_queue", w.taskQueue).
		Msg("Starting LRO Temporal worker")

	if w.jobScheduler != nil {
		go w.runSchedulerReconcileLoop(ctx)
	}

	// Run the worker (this blocks)
	err := w.temporalWorker.Run(worker.InterruptCh())
	if err != nil {
		return fmt.Errorf("worker failed: %w", err)
	}

	return nil
}

func (w *LROWorker) runSchedulerReconcileLoop(ctx context.Context) {
	ticker := time.NewTicker(jobscheduler.SchedulerReconcileInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.D

one():
			return
		case <-ticker.C:
			if err := w.jobScheduler.ReconcileState(ctx); err != nil {
				log.Error().Err(err).Msg("Error reconciling job scheduler state")
			}
		}
	}
}

// registerWorkflowsAndActivities registers all workflows and activities based on worker type
