func (w *LROWorker) GetAvailableCapacity(ctx context.Context, req *dwpb.GetAvailableCapacityRequest) (*dwpb.GetAvailableCapacityResponse, error) {
	if w.availableCapacityFromGlobalCapacityServer && w.globalCapacityClient != nil {
		return w.getAvailableCapacityFromGlobalCapacityServer(ctx, req)
	}
	return w.getAvailableCapacityFromClusterManager(ctx, req)
}

// getAvailableCapacityFromClusterManager is the legacy per-cluster Kubernetes
// List path (via AvailableCapacityCache), retained as the fallback when no
// global capacity client is configured.
func (w *LROWorker) getAvailableCapacityFromClusterManager(ctx context.Context, req *dwpb.GetAvailableCapacityRequest) (*dwpb.GetAvailableCapacityResponse, error) {
	resp := &dwpb.GetAvailableCapacityResponse{
		AvailableCapacity: []*dwpb.GetAvailableCapacityResponse_Capacity{},
	}

	// If a list of regions is provided, we only return the available capacity for the regions in the list
	minPriority := int32(constants.PriorityValueDeployment)
	if req.MinPriority != nil {
		minPriority = *req.MinPriority
	}

	if len(req.Regions) > 0 {
		for _, region := range req.Regions {
			client, exists := w.clusterManager.Clients[region]
			if !exists || client == nil {
				continue
			}

			// Check if capacity cache is available
			if client.AvailableCapacityCache == nil {
				continue
			}

			// Check if this accelerator type is supported in this region
			acceleratorTypes, err := w.regionBasedRuntime.GetAcceleratorTypesForRegion(region)
			if err != nil {
				// Region not configured, skip
				continue
			}
			if _, supported := acceleratorTypes[req.AcceleratorType]; !supported {
				continue
			}

			count, err := client.AvailableCapacityCache.Get(ctx, clustermanager.CapacityCacheKey{
				AcceleratorType:    req.AcceleratorType,
				MinPriority:        minPriority,
				TaintExclusionMode: req.TaintExclusionMode,
			})
			if err != nil {
				log.Warn().Err(err).Msgf("Error getting free GPUs for region %v", region)
				continue
			}
			if count == 0 {
				continue
			}
			resp.AvailableCapacity = append(resp.AvailableCapacity, &dwpb.GetAvailableCapacityResponse_Capacity{
				Region: region,
				Count:  count,
			})
		}
		return resp, nil
	}

	// Otherwise, if a multi-region is provided, we return the available capacity for the regions in the multi-region
	for region, client := range w.clusterManager.Clients {
		if client == nil {
			continue
		}

		// Skip clusters that do not accept autoplacement for this hardware type.
		if !client.AcceptAutoPlacement(clustermanager.WithAcceleratorType(req.AcceleratorType)) {
			continue
		}

		// Check if capacity cache is available
		if client.AvailableCapacityCache == nil {
			continue
		}

		// Check if region belongs to the requested multi-region group
		if req.MultiRegion != gpb.MultiRegion_MULTI_REGION_UNSPECIFIED {
			if !w.clusterRegistry.IsValidMultiRegion(req.MultiRegion) {
				return nil, fmt.Errorf("invalid multi-region: %v", req.MultiRegion)
			}
			if !w.clusterRegistry.RegionGroupContains(req.MultiRegion, region) {
				continue
			}
		}

		// Check if this accelerator type is supported in this region
		acceleratorTypes, err := w.regionBasedRuntime.GetAcceleratorTypesForRegion(region)
		if err != nil {
			// Region not configured, skip
			continue
		}
		if _, supported := acceleratorTypes[req.AcceleratorType]; !supported {
			continue
		}

		count, err := client.AvailableCapacityCache.Get(ctx, clustermanager.CapacityCacheKey{
			AcceleratorType:    req.AcceleratorType,
			MinPriority:        minPriority,
			TaintExclusionMode: req.TaintExclusionMode,
		})
		if err != nil {
			log.Warn().Err(err).Msgf("Error getting free GPUs for region %v", region)
			continue
		}
		if count == 0 {
			continue
		}
		resp.AvailableCapacity = append(resp.AvailableCapacity, &dwpb.GetAvailableCapacityResponse_Capacity{
			Region: region,
			Count:  count,
		})
	}
	return resp, nil
}

// availableCapacitySlack is the per-region GPU buffer GetAvailableCapacity
// withholds so callers never pack a region to its last GPU. Mirrors the legacy
// fetchAvailableCapacity slack the cluster_manager path applied.
const availableCapacitySlack = int32(8)

// getAvailableCapacityFromGlobalCapacityServer answers GetAvailableCapacity from
// global_capacity_server instead of the legacy per-cluster Kubernetes List path.
func (w *LROWorker) getAvailableCapacityFromGlobalCapacityServer(ctx context.Context, req *dwpb.GetAvailableCapacityRequest) (*dwpb.GetAvailableCapacityResponse, error) {
	minPriority := int32(constants.PriorityValueDeployment)
	if req.MinPriority != nil {
		minPriority = *req.MinPriority
	}

	regions, err := w.resolveAvailableCapacityRegions(req)
	if err != nil {
		return nil, err
	}
	if len(regions) == 0 {
		return &dwpb.GetAvailableCapacityResponse{}, nil
	}

	// Mirror the legacy cluster_manager inputs: the LRO worker

path keyed the
	// capacity cache on (accelerator, min priority, taint mode) and did not
	// thread AllowedTaintKeys, so leave it unset here to preserve behavior.
	counts, err := globalcapacity.AvailableCapacityByRegion(ctx, w.globalCapacityClient, globalcapacity.AvailableCapacityRequest{
		AcceleratorType:    req.AcceleratorType,
		Regions:            regions,
		MinPriority:        minPriority,
		TaintExclusionMode: gcpb.TaintExclusionMode(req.TaintExclusionMode),
		Slack:              availableCapacitySlack,
	})
	if err != nil {
		return nil, err
	}

	resp := &dwpb.GetAvailableCapacityResponse{}
	for _, region := range regions {
		count, ok := counts[region]
		if !ok || count <= 0 {
			continue
		}
		resp.AvailableCapacity = append(resp.AvailableCapacity, &dwpb.GetAvailableCapacityResponse_Capacity{
			Region: region,
			Count:  count,
		})
	}
	return resp, nil
}

// resolveAvailableCapacityRegions returns the regions GetAvailableCapacity should
// query, mirroring the legacy cluster_manager path's region selection: the
// explicit Regions (filtered to managed, accelerator-supporting regions), or the
// multi-region members that accept auto-placement for the accelerator.
// TODO(kexiang): unify with deployment_watcher.resolveAvailableCapacityRegions
func (w *LROWorker) resolveAvailableCapacityRegions(req *dwpb.GetAvailableCapacityRequest) ([]gpb.Region, error) {
	if len(req.Regions) > 0 {
		var regions []gpb.Region
		for _, region := range req.Regions {
			if client, exists := w.clusterManager.Clients[region]; !exists || client == nil {
				continue
			}
			if !w.acceleratorSupportedInRegion(region, req.AcceleratorType) {
				continue
			}
			regions = append(regions, region)
		}
		return regions, nil
	}

	if req.MultiRegion != gpb.MultiRegion_MULTI_REGION_UNSPECIFIED && !w.clusterRegistry.IsValidMultiRegion(req.MultiRegion) {
		return nil, fmt.Errorf("invalid multi-region: %v", req.MultiRegion)
	}
	var regions []gpb.Region
	for region, client := range w.clusterManager.Clients {
		if client == nil {
			continue
		}
		if !client.AcceptAutoPlacement(clustermanager.WithAcceleratorType(req.AcceleratorType)) {
			continue
		}
		if req.MultiRegion != gpb.MultiRegion_MULTI_REGION_UNSPECIFIED && !w.clusterRegistry.RegionGroupContains(req.MultiRegion, region) {
			continue
		}
		if !w.acceleratorSupportedInRegion(region, req.AcceleratorType) {
			continue
		}
		regions = append(regions, region)
	}
	return regions, nil
}

// acceleratorSupportedInRegion reports whether the region is configured to run
// the given accelerator type, matching the legacy path's per-region check.
func (w *LROWorker) acceleratorSupportedInRegion(region gpb.Region, acceleratorType gpb.AcceleratorType) bool {
	acceleratorTypes, err := w.regionBasedRuntime.GetAcceleratorTypesForRegion(region)
	if err != nil {
		return false
	}
	_, supported := acceleratorTypes[acceleratorType]
	return supported
}

// makeAcceleratorTypeMap creates a map of accelerator types available in a specific region
func makeAcceleratorTypeMap(region gpb.Region, acceleratorTypeToRegions map[gpb.AcceleratorType][]gpb.Region) map[gpb.AcceleratorType]bool {
	acceleratorTypeMap := make(map[gpb.AcceleratorType]bool)
	for acceleratorType, regions := range acceleratorTypeToRegions {
		for _, r := range regions {
			if r == region {
				acceleratorTypeMap[acceleratorType] = true
			}
		}
	}
	return acceleratorTypeMap
}

