	assert.Equal(t, "COMPLETED", result.Status)

	// Verify we have all 5 epoch outputs (4 restored + 1 newly executed)
	assert.Len(t, result.EpochOutputs, 5, "Should have 5 epoch outputs total")

	// Verify restored epochs (0-3) have TrackedResource cleared
	for i := 0; i < 4; i++ {
		assert.Empty(t, result.EpochOutputs[i].TrackedResource,
			"Restored epoch %d should have empty TrackedResource to avoid duplicate cleanup", i)
		assert.NotEmpty(t, result.EpochOutputs[i].RLORJobName,
			"Restored epoch %d should preserve RLORJobName for early stop check", i)
		assert.NotEmpty(t, result.EpochOutputs[i].OutputModel,
			"Restored epoch %d should preserve OutputModel", i)
	}

	// Verify the newly executed epoch (chunk 4) has TrackedResource intact
	assert.NotEmpty(t, result.EpochOutputs[4].TrackedResource,
		"Newly executed epoch should have TrackedResource for cleanup")
	assert.Len(t, result.EpochOutputs[4].TrackedResource, 2,
