	// Verify only 1 new epoch workflow was executed (chunk 4)
	assert.Equal(t, 1, epochCallCount, "Should only execute chunk 4")

	// Verify no early stop happened (would have failed if array access was out of bounds)
	assert.Equal(t, "COMPLETED", result.Status, "Job should complete normally without early stop")
