	}, activity.RegisterOptions{Name: "UpdateRFTJobStats"})

	env.OnActivity("UpdateRFTJobMetaInfo", mock.Anything, mock.Anything).Return(nil)
	env.OnActivity("UpdateRFTJobStats", mock.Anything, mock.Anything).Return(nil)

	// Register the dataset validation workflow
	env.RegisterWorkflow(DatasetValidationWork

flow)

	// Mock dataset validation workflow
	env.OnWorkflow(DatasetValidationWorkflow, mock.Anything, mock.Anything).Return(
		func(ctx workflow.Context, input DatasetValidationWorkflowInput) (*DatasetValidationWorkflowOutput, error) {
			return &DatasetValidationWorkflowOutput{
				JobName: "validation-job-123",
			}, nil
		},
	)

	// Register child workflows
	env.RegisterWorkflow(RFTEpochWorkflow)

	// Register cleanup activity
	env.RegisterActivity(&activities.CleanupActivity{})
	env.OnActivity("ExecuteComprehensiveCleanup", mock.Anything, mock.Anything).Return(nil)

	// Track the epoch index to determine behavior
	epochCounter := 0

	// Mock child workflow execution
	// Epoch 0: Successful training, produces model
	// Epoch 1: Successful training, produces model
	// Epoch 2 (last): Empty dataset, skips training, returns input model
	env.OnWorkflow(RFTEpochWorkflow, mock.Anything, mock.Anything, mock.Anything).Return(
		func(ctx workflow.Context, input RFTEpochWorkflowInput, workflowMetaData WorkflowMetaData) (*RFTEpochWorkflowOutput, error) {
			currentEpoch := epochCounter
			epochCounter++

			if currentEpoch < 2 {
				// First two epochs: successful training
				return &RFTEpochWorkflowOutput{
					RolloutJobName:          fmt.Sprintf("rollout-job-%d", currentEpoch),
					EvaluationJobName:       fmt.Sprintf("eval-job-%d", currentEpoch),
					RLORJobName:             fmt.Sprintf("rlor-job-%d", currentEpoch),
					OutputModel:             input.TrainingConfig.OutputModel, // Use the expected output model
					Status:                  "COMPLETED",
					EvaluationOutputDataset: fmt.Sprintf("eval-dataset-%d", currentEpoch),
					EvaluationStats:         `{"total_count": 100}`,
				}, nil
			} else {
				// Last epoch: training skipped due to empty dataset
				// Returns the input model instead of the expected output model
				return &RFTEpochWorkflowOutput{
					RolloutJobName:          fmt.Sprintf("rollout-job-%d", currentEpoch),
					EvaluationJobName:       fmt.Sprintf("eval-job-%d", currentEpoch),
					RLORJobName:             "skipped",   // RLOR training was skipped
					OutputModel:             input.Model, // Returns input model (from previous successful training)
					Status:                  "COMPLETED",
					EvaluationOutputDataset: fmt.Sprintf("eval-dataset-%d", currentEpoch),
					EvaluationStats:         `{"total_count": 100}`,
				}, nil
			}
		},
	)

	// The expected final output model that user specified
	expectedFinalModel := "accounts/test-account/models/final-output-model"

	input := RFTJobWorkflowInput{
		AccountID:               "test-account",
		JobID:                   "test-job-123",
		DatasetName:             "accounts/test-account/datasets/training",
		DatasetGcsUri:           "gs://bucket/training-data",
		Evaluator:               &database.Evaluator{EvaluatorName: *resourcename.NewEvaluatorName("test-account", "evaluator-123")},
		BaseModel:               "accounts/test-account/models/base-model",
		OutputModel:             expectedFinalModel, // User expects this as final model
		CreatedBy:               "test-user",
		Region:                  gpb.Region_US_VIRGINIA_1,
		EndingAssistantMessages: "drop",
		MetadataPath:            "", // No metadata path for this test (activity will handle nil)
		TrainingConfig: &gpb.BaseTrainingConfig{
			Epochs:           3, // 3 epochs to test multiple iterations
			AcceleratorType:  gpb.AcceleratorType_NVIDIA_H100_80GB,
			AcceleratorCount: 1,
			Region:           gpb.Region_US_VIRGINIA_1,
		},
		WandbConfig: &gpb.WandbConfig{
			Enabled: false,
		},
		InferenceParameters: &gpb.ReinforcementFineTuningJob_InferenceParameters{},
		EvalAutoCarveout:    true,
		ChunkSize:           0, // No chunking, use multiple epochs instead
		RLORDebug:           false,
		Environment:         "dev",
		DisableHotReload:    true,
	}

	metaData := WorkflowMetaData{
		WorkflowQueue:       "test-workflow-queue",
		GoActivityQueue:     "test-go-activity-queue",
		PythonActivityQueue: "test-python-activity-queue",
	}

	env.ExecuteWorkflow(RFTJobWorkflow, input, metaData)

	require.True(t, env.IsWorkflowCompleted())
	require.NoError(t, env.GetWorkflowError())

	var result RFTJobWorkflowOutput
	require.NoError(t, env.GetWorkflowResult(&result))

	// Verify workflow completed successfully
	assert.Equal(t, "COMPLETED", result.Status)
	assert.Equal(t, int32(3), result.TotalEpochs)
	assert.Equal(t, int32(0), result.TotalChunks)

	// Verify we have all 3 epoch outputs
	assert.Len(t, result.EpochOutputs, 3)

	// Verify first two epochs completed with training
	assert.NotEqual(t, "skipped", result.EpochOutputs[0].RLORJobName,
		"First epoch should have completed training")
	assert.NotEqual(t, "skipped", result.EpochOutputs[1].RLORJobName,
		"Second epoch should have completed training")

	// Verify last epoch was skipped (empty dataset after transformation)
	assert.Equal(t, "skipped", result.EpochOutputs[2].RLORJobName,
		"Last epoch should have skipped training due to e

mpty dataset")

	// CRITICAL: Verify that FinalOutputModel is the actual last trained model,
	// NOT the user-specified model name, because the last iteration was skipped
	assert.NotEqual(t, expectedFinalModel, result.FinalOutputModel,
		"FinalOutputModel should NOT be the user-specified model when last iteration is skipped")
	assert.Equal(t, result.EpochOutputs[2].OutputModel, result.FinalOutputModel,
		"FinalOutputModel should match the last epoch's actual output model (from previous successful training)")
}

// TestRFTJobWorkflow_HotReloadDeploymentTrackedBeforeActivity verifies that the hot-reload
// deployment is tracked for cleanup BEFORE CreateOrGetDeployment activity is called.
// This prevents resource leaks when the workflow is cancelled during deployment creation.
func TestRFTJobWorkflow_HotReloadDeploymentTrackedBeforeActivity(t *testing.T) {
	testSuite := &testsuite.WorkflowTestSuite{}
	env := testSuite.NewTestWorkflowEnvironment()

	registerMockRFTJobActivities(env)

	env.RegisterWorkflow(DatasetValidationWorkflow)
	env.RegisterWorkflow(RFTEpochWorkflow)

	// Register activities
	env.RegisterActivity(&activities.CleanupActivity{})
	env.RegisterActivityWithOptions(func(ctx context.Context, input activities.CreateOrGetDeploymentInput) (*activities.CreateOrGetDeploymentOutput, error) {
		return nil, nil
	}, activity.RegisterOptions{Name: "CreateOrGetDeployment"})

	env.OnWorkflow(DatasetValidationWorkflow, mock.Anything, mock.Anything).Return(
		&DatasetValidationWorkflowOutput{JobName: "validation-job"}, nil,
	)

	// Track whether deployment was in cleanup resources
	var cleanupCalledWithDeployment bool
	expectedDeploymentName := "accounts/test-account/deployments/rft-hotreload-deploy-tracking-test"

	// Mock CreateOrGetDeployment to block and allow cancellation
	env.OnActivity("CreateOrGetDeployment", mock.Anything, mock.Anything).Return(
		func(ctx context.Context, input activities.CreateOrGetDeploymentInput) (*activities.CreateOrGetDeploymentOutput, error) {
			// Verify deployment name matches expected pattern
			assert.Equal(t, expectedDeploymentName, input.DeploymentName)
			// Block until context is cancelled - simulating long-running deployment creation
			<-ctx.Done()
			return nil, ctx.Err()
		},
	)

	// Mock cleanup to capture what resources are being cleaned up
	env.OnActivity("ExecuteComprehensiveCleanup", mock.Anything, mock.Anything).Return(
		func(ctx context.Context, input activities.ExecuteComprehensiveCleanupInput) error {
			// Check if deployment is in the cleanup resources
			for _, resource := range input.Resources {
				if resource.ResourceType == common.ResourceTypeK8sDeployment &&
					resource.ResourceName == expectedDeploymentName {
					cleanupCalledWithDeployment = true
				}
			}
			return nil
		},
	)

	input := RFTJobWorkflowInput{
		AccountID:               "test-account",
		JobID:                   "deploy-tracking-test",
		DatasetName:             "accounts/test-account/datasets/training",
		Evaluator:               &database.Evaluator{EvaluatorName: *resourcename.NewEvaluatorName("test-account", "evaluator-123")},
		BaseModel:               "accounts/test-account/models/base-model",
		OutputModel:             "accounts/test-account/models/output-model",
		CreatedBy:               "test-user",
		Region:                  gpb.Region_US_VIRGINIA_1,
		EndingAssistantMessages: "drop",
		DeploymentShape:         "accounts/fireworks/deploymentShapes/test/versions/v1",
		TrainingConfig: &gpb.BaseTrainingConfig{
			Epochs:           1,
			AcceleratorType:  gpb.AcceleratorType_NVIDIA_H100_80GB,
			AcceleratorCount: 1,
			Region:           gpb.Region_US_VIRGINIA_1,
		},
		WandbConfig: &gpb.WandbConfig{
			Enabled: false,
		},
		InferenceParameters: &gpb.ReinforcementFineTuningJob_InferenceParameters{},
		EvalAutoCarveout:    true,
		ChunkSize:           0,
		RLORDebug:           false,
		Environment:         "dev",
		DisableHotReload:    false, // Enable hot-reload
	}

	metaData := WorkflowMetaData{
		WorkflowQueue:       "test-workflow-queue",
		GoActivityQueue:     "test-go-activity-queue",
		PythonActivityQueue: "test-python-activity-queue",
	}

	// Cancel the workflow while CreateOrGetDeployment is executing
	env.RegisterDelayedCallback(func() {
		env.CancelWorkflow()
	}, 100*time.Millisecond)

	env.ExecuteWorkflow(RFTJobWorkflow, input, metaData)

	require.True(t, env.IsWorkflowCompleted())

	// Workflow should be cancelled
	err := env.GetWorkflowError()
	require.Error(t, err, "Workflow should have an error due to cancellation")

	// CRITICAL: Verify that cleanup was called with the deployment name
	// This proves the deployment was tracked BEFORE CreateOrGetDeployment completed
	assert.True(t, cleanupCalledWithDeployment,
		"ExecuteComprehensiveCleanup should be called with deployment name even when "+
			"CreateOrGetDeployment is cancelled mid-execution. This verifies the deployment "+
			"is tracked for cleanup BEFORE the activity is called.")
}

