@torch.library.custom_op("fireworks::quantize_mxfp4_hopper", mutates_args=())
def _quantize_mxfp4_hopper_op(w: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
    w, w_scale = downcast_to_mxfp(w.to(torch.bfloat16), torch.uint8, axis=1)
    w = convert_layout(wrap_torch_tensor(w, dtype=FP4), HopperMXValueLayout(mx_axis=-2, mma_version=3))
    w_scale = convert_layout(wrap_torch_tensor(w_scale), HopperMXScaleLayout(mx_axis=-2, num_warps=8))
    return w.storage.data, w_scale.storage.data


@_quantize_mxfp4_hopper_op.register_fake
def _(x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
    lead_dims = x.shape[:-2]
    # NB: we are transposing x tensor (making it column-major).
    m = x.shape[-1]
    k = x.shape[-2]
    assert k % 2 == 0  # 1 uint8 value fits 2 fp4 values.

    # See docs on HopperMXValueLayout for details.
    shape = (*lead_dims, ((m + 16 - 1) // 16) * 4, ((k + 64 - 1) // 64) * 128)
    x_fp4 = x.new_empty(shape, dtype=torch.uint8).transpose(-2, -1)

    mx_scale_shape = (*lead_dims, ((m + 256 - 1) // 256) * 8, ((k + 64 - 1) // 64) * 64)
    mx_scale = x.new_empty(mx_scale_shape, dtype=torch.uint8).transpose(-2, -1)

    return x_fp4, mx_scale


@torch.library.custom_op("fireworks::quantize_mxfp4_blackwell", mutates_args=())
def _quantize_mxfp4_blackwell_op(w: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
    value_layout = layout.make_default_matmul_mxfp4_w_layout(mx_axis=1)
    scale_layout = layout.make_default_matmul_mxfp4_w_scale_layout(mx_axis=1, num_warps=4)
    w, w_scale = downcast_to_mxfp(w.to(torch.bfloat16), torch.uint8, axis=1)
    w = convert_layout(wrap_torch_tensor(w, dtype=FP4), value_layout)
    w_scale = convert_layout(wrap_torch_tensor(w_scale), scale_layout)
    return w.storage.data, w_scale.storage.data


