    m = x.shape[-1]
    k = x.shape[-2]
    assert k % 2 == 0  # 1 uint8 value fits 2 fp4 values.

    shape = (*lead_dims, m, k)
    x_fp4 = x.new_empty(shape, dtype=torch.uint8).transpose(-2, -1)

    k_mx = (k + 32 - 1) // 32
    B = math.prod(lead_dims)
    K_pad = (k_mx + 8 - 1) // 8 * 8
    N_pad = (m + 128 - 1) // 128 * 128
    mx_shape = (1, B * N_pad // 128, K_pad // 4, 2, 256)
    x_scale = x.new_empty(mx_shape, dtype=torch.uint8)

    return x_fp4, x_scale


