def _manifest_if_uninitialized(w: torch.Tensor) -> torch.Tensor:
    """Manifest only fake-weight (uninitialized) PLLTs before quantization.

    For fake weights, the PLLT dispatch wraps quantize results in a derived PLLT
    that ``manifest_uninitialized`` later replaces with row-major zeros, losing
    the column-major layout the matmul kernel requires.  Manifesting here forces
    the quantize op to run on concrete zeros and produce correct strides.

    Real-weight PLLTs are left untouched — they flow through the normal manifest
    DAG which handles parallel I/O efficiently.
    """
    if not isinstance(w, Manifestable):
        return w
    loaders = collect_loaders(w)
    if loaders and all(isinstance(l, UninitializedTensorLoader) for l in loaders):
        return w.manifest()
    return w


def quantize_mxfp4(w):
    w = _manifest_if_uninitialized(w)
    if is_blackwell_and_higher():
        x_fp4, x_scale = torch.ops.fireworks.quantize_mxfp4_blackwell(w)
        return x_fp4, x_scale
    elif is_hopper():
        x_fp4, x_scale = torch.ops.fireworks.quantize_mxfp4_hopper(w)
        return x_fp4, x_scale
    else:
        raise ValueError(f"Unsupported compute capability: {get_compute_capability()}")


def quantize_mxfp8(w: torch.Tensor, weight_dtype: torch.dtype = torch.float8_e4m3fn):
    """
    Quantize weights to MXFP8 with Strided layouts for values and scales.

    By default, MXFP8 uses e4m3fn for weights.
    """
    w = _manifest_if_uninitialized(w)
    return torch.ops.fireworks.quantize_mxfp8(w, weight_dtype)


@torch.library.custom_op("fireworks::quantize_mxfp8", mutates_args=())
def _quantize_mxfp8_op(
    w: torch.Tensor, weight_dtype: torch.dtype = torch.float8_e4m3fn
) -> Tuple[torch.Tensor, torch.Tensor]:
    w_q, w_scale = downcast_to_mxfp(w.to(torch.bfloat16), weight_dtype, axis=1)
    w_q = convert_layout(wrap_torch_tensor(w_q, dtype=weight_dtype), StridedLayout(-2))
    w_scale = convert_layout(wrap_torch_tensor(w_scale), StridedLayout(-2))
    return w_q.storage.data, w_scale.storage.data


@_quantize_mxfp8_op.register_fake
def _(x: torch.Tensor, weight_dtype: torch.dtype = torch.float8_e4m3fn) -> Tuple[torch.Tensor, torch.Tensor]:
    lead_dims = x.shape[:-2]
    k = x.shape[-2]
    n = x.shape[-1]
    x_fp8 = x.new_empty((*lead_dims, k, n), dtype=weight_dtype)
    x_scale_shape = (*lead_dims, triton.cdiv(k, MXFP_BLOCK_SIZE.value), n)
    x_scale = x.new_empty(x_scale_shape, dtype=torch.uint8)
    return x_fp8, x_scale


def to_triton_tensors(
    x_fp4: torch.Tensor, x_scale: torch.Tensor, shape: torch.Size
) -> Tuple[TritonTensor, TritonTensor]:
    if is_blackwell_and_higher():
        x_fp4_tensor = TritonTensor(TritonStorage(x_fp4, BlackwellMXValueLayout()), FP4, shape=shape)
        x_scale_shape = (*shape[:-2], triton.cdiv(shape[-2], MXFP_BLOCK_SIZE.value), shape[-1])
        x_scale_tensor = TritonTensor(
            TritonStorage(x_scale, BlackwellMXScaleLayout()), torch_dtype_to_dtype(x_scale.dtype), shape=x_scale_shape
        )
    elif is_hopper():
        x_fp4_tensor = TritonTensor(
            TritonStorage(x_fp4, HopperMXValueLayout(mx_axis=-2, mma_version=3)), FP4, shape=shape
        )
        x_scale_shape = (*shape[:-2], (shape[-2] + 32 - 1) // 32, shape[-1])
        x_scale_tensor = TritonTensor(
            TritonStorage(x_scale, HopperMXScaleLayout(mx_axis=-2, num_warps=8)),
            torch_dtype_to_dtype(x_scale.dtype),
            shape=x_scale_shape,
        )
    else:
        raise ValueError(f"Unsupported compute capability: {get_compute_capability()}")
    return x_fp4_tensor, x_scale_tensor


def to_triton_tensors_fp8(
    x_fp8: torch.Tensor, x_scale: torch.Tensor, shape: torch.Size, weight_dtype: torch.dtype = torch.float8_e4m3fn
) -> Tuple[TritonTensor, TritonTensor]:
    if is_blackwell_and_higher():
        value_layout = BlackwellMXValueLayout()
        value_transform = value_layout.make_transformation(list(shape), False)
        x_fp8_tensor = TritonTensor(
            TritonStorage(value_transform.swizzle_data(x_fp8), value_layout),
            torch_dtype_to_dtype(weight_dtype),
            shape=shape,
        )
        x_scale_shape = (*shape[:-2], triton.cdiv(shape[-2], MXFP_BLOCK_SIZE.value), shape[-1])
        scale_layout = BlackwellMXScaleLayout()
        scale_transform = scale_layout.make_transformation(list(x_scale_shape), False)
        x_scale_tensor = TritonTensor(
            TritonStorage(scale_transform.swizzle_data(x_scale), scale_layout),
            torch_dtype_to_dtype(x_scale.dtype),
            shape=x_scale_shape,
        )
    else:
        x_fp8_tensor = wrap_torch_tensor(x_fp8, dtype=weight_dtype)
        x_fp8_tensor = convert_layout(x_fp8_tensor, StridedLayout(-2))
        x_scale_tensor = wrap_torch_tensor(x_scale)
        x_scale_tensor = convert_layout(x_scale_tensor, StridedLayout(-2))
    return x_fp8_tensor, x_scale_tensor


