def _preprocess_segments_for_captions(segments: List[TranscribeSegment]):
    # HACK: the Whisper result writers (https://github.com/openai/whisper/blob/90db0de1896c23cbfaf0c58bc2d30665f709f170/whisper/utils.py#L200)
    # join together text from words without any separator. There seems to be some
    # sort of misaligned contract of whether the words returned in the `segment`
    # structure have whitespace embedded (as in the output of e.g. TikToken)
    #
    # The OAI API returns `words` without any whitespace. This leads me to
    # believe that their API may internally process words on the original
    # tiktoken tokens, then calls strip() on them before returning to the
    # user
    #
    # Nevertheless, we are going to try to make the SRT/VTT writers
    # work by prepending a space to each word after the first word, in each
    # segment
    new_segs = [copy.copy(seg) for seg in segments]

    for segment in new_segs:
        new_words: List[TranscribeWord] = []
        for i, word in enumerate(segment.words):
            if word.start is None:
                word.start = segment.start
            if word.end is None:
                word.end = segment.end

            if i > 0:
                word = replace(word, word=f" {word.word}")

            new_words.append(word)
        segment.words = new_words

    return new_segs


def _format_transcription_verbose_json(
    request_id: str,
    transcribe_text: TranscribeText,
    duration_sec: Optional[float],
    params: Union[TranscriptionParams, StreamingTranscriptionParams, TranslationParams, AlignmentParams],
) -> Dict:
    timestamp_granularities = []
    if isinstance(params, (TranscriptionParams, TranslationParams)):
        timestamp_granularities = params.timestamp_granularities
    elif isinstance(params, (AlignmentParams, StreamingTranscriptionParams)):
        timestamp_granularities = [TimestampGranularity.WORD, TimestampGranularity.SEGMENT]
    else:
        raise UserError(f"Unknown params type: {type(params)}")

    # Serialize
    words = None
    segments = None
    if timestamp_granularities:
        include_words = TimestampGranularity.WORD in timestamp_granularities
        segments_dicts = [s.to_dict(include_words=include_words) for s in transcribe_text.segments]
        if TimestampGranularity.WORD in timestamp_granularities:
            words = [w for s in segments_dicts for w in s["words"]]
        if TimestampGranularity.SEGMENT in timestamp_granularities:
            segments = segments_dicts

    text_dict = {
        "task": "transcribe",
        "language": transcribe_text.language,
        "text": transcribe_text.text,
        "request_id": request_id,
    }
    if words is not None:
        text_dict["words"] = words
    if segments is not None:
        text_dict["segments"] = segments
    if duration_sec is not None:
        text_dict["duration"] = duration_sec
    if transcribe_text.embeddings is not None:
        text_dict["embeddings"] = transcribe_text.embeddings

    return text_dict


