class PrerecordedTranscriptionsResource:
    async def report_usage(self, account_id: str, bytes_received: int) -> bool:
        accepted = True
        # Skip rate limit check for health check requests
        if account_id == "health_check":
            return accepted
        if _ratelimit_verifier is not None:
            try:
                with fireutil.log_time_if("Reporting rate limit", took_more_than=0.1):
                    rate_limit_response: RatelimitResponse = await asyncio.wait_for(
                        _ratelimit_verifier.check_and_update(
                            user_account=account_id,
                            metric=_args.prerecorded_rate_limit_metric_name,
                            cost=bytes_received,
                            default_limit=self._get_rate_limit(
                                account_id,
                                _args.prerecorded_bandwidth_limit_bytes,
                                _args.account_prerecorded_limit_bytes_override,
                            ),
                        ),
                        timeout=_args.rate_limit_timeout_seconds,
                    )
                    logger.info(f"Ratelimit response {account_id} {rate_limit_response}")
                    accepted = rate_limit_response.accepted
            except asyncio.TimeoutError:
                logger.warning(
                    f"Ratelimit check timed out after {_args.rate_limit_timeout_seconds}s for {account_id=}, accepting request"
                )
                accepted = True
            except AttributeError:
                logger.warning(f"Ratelimit check error for {account_id=}, accepting request")
                accepted = True

        return accepted

    def _get_rate_limit(
        self, account_id: str, bytes_limit: int, account_prerecorded_limit_bytes_override: Dict[str, float]
    ) -> int:
        # Override bytes limit by account-specific limit
        if account_id in account_prerecorded_limit_bytes_override:
            bytes_limit = account_prerecorded_limit_bytes_override[account_id]
        return bytes_limit


