o",
                "json",
                f"--request-timeout={request_timeout_seconds}s",
            ],
            timeout_seconds=process_timeout_seconds,
        )
        if result is None:
            last_error = f"kubectl process timed out after {process_timeout_seconds}s"
        elif result.returncode != 0:
            last_error = compact_error(result.stderr or result.stdout)
        else:
            try:
                payload = json.loads(result.stdout)
            except json.JSONDecodeError as exc:
                last_error = f"invalid kubectl JSON: {exc}"
            else:
                items = payload.get("items")
                if not isinstance(items, list):
                    return None, "kubectl JSON did not contain an items list"
                return items, None

        if attempt < max_attempts:
            if not quiet:
                log(
                    f"  attempt {attempt}/{max_attempts} failed for {context}: "
                    f"{last_error}; retrying in {retry_delay_seconds:g}s"
                )
            time.sleep(retry_delay_seconds)

    return None, last_error


def compact_error(text: str, max_len: int = 220) -> str:
    one_line = " ".join(line.strip() for line in text.splitlines() if line.strip())
    if len(one_line) <= max_len:
        return one_line
    return one_line[: max_len - 3] + "..."


def pod_template_containers(deployment: dict[str, Any]) -> list[dict[str, Any]]:
    return deployment.get("spec", {}).get("template", {}).get("spec", {}).get("containers", [])


def serving_container(deployment: dict[str, Any]) -> dict[str, Any] | None:
    for container in pod_template_containers(deployment):
        if container.get("name") == SERVING_CONTAINER_NAME:
            return container
    return None


def container_tokens(container: dict[str, Any]) -> list[str]:
    tokens: list[str] = []
    for field_name in ("command", "args"):
        values = container.get(field_name, [])
        if isinstance(values, list):
            tokens.extend(str(value) for value in values)
        elif values:
            tokens.append(str(values))
    return tokens


def has_flag(tokens: list[str], flag: str) -> bool:
    return any(token == flag or token.startswith(f"{flag}=") for token in tokens)


def parse_int(value: Any, default: int = 0) -> int:
    if value is None:
        return default
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def parse_gpu_quantity(value: Any) -> float:
    if value is None:
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)

    text = str(value).strip()
    if not text:
        return 0.0

    # Kubernetes extended resources are normally integers, but this accepts
    # standard milli quantities in case a context reports normalized resources.
    if text.endswith("m"):
        try:
            return float(text[:-1]) / 1000
        except ValueError:
            return 0.0

    try:
        return float(text)
    except ValueError:
        return 0.0


def serving_container_gpu_request(container: dict[str, Any]) -> float:
    requests = container.get("resources", {}).get("requests", {})
    return parse_gpu_quantity(requests.get(GPU_RESOURCE_NAME))


def image_version(image: str) -> str:
    if not image:
        return ""

    image_without_digest, separator, digest = image.partition("@")
    last_segment = image_without_digest.rsplit("/", maxsplit=1)[-1]
    if ":" in last_segment:
        return last_segment.rsplit(":", maxsplit=1)[-1]
    if separator:
        return digest[:19] if digest else ""
    return image


def deployment_row(context: str, deployment: dict[str, Any]) -> DeploymentRow | None:
    container = serving_container(deployment)
    if container is None:
        return None

    tokens = container_tokens(container)
    if not has_flag(tokens=tokens, flag=HOTLOAD_BASE_MODEL_WATCH_DIR_FLAG):
        return None

    # K8s args are authoritative. firectl Extra Values like
    # enableHotloadP2PCollective=true is operator intent only - the chart that
    # rendered this deployment may have ignored it, so the actual serving args
    # are the ground truth.
    hotload_type = "collective" if has_flag(tokens=tokens, flag=HOTLOAD_P2P_COLLECTIVE_FLAG) else "legacy"

    metadata = deployment.get("metadata", {})
    labels = metadata.get("labels", {}) or {}
    current_replicas = parse_int(deployment.get("status", {}).get("replicas"))
    desired_replicas = parse_int(deployment.get("spec", {}).get("replicas"), default=1)
    gpus_per_replica = serving_container_gpu_request(container)

    return DeploymentRow(
        cluster=context,
        hotload_type=hotload_type,
        account_id=str(labels.get(ACCOUNT_ID_LABEL, "")).strip(),
        deployment_id=str(labels.get(DEPLOYMENT_ID_LABEL, "")).strip(),
        current_replicas=current_replicas,
        desired_replicas=desired_replicas,
        gpus=gpus_per_replica * current_

replicas,
        create_date=metadata.get("creationTimestamp", ""),
        image_version=image_version(str(container.get("image", ""))),
        deployment_shape_version="",
        latest_shape=False,
        official_shape=False,
        firectl_status="",
        created_by="",
        firectl_profile="",
    )


def parse_firectl_text_output(text: str) -> dict[str, str]:
    """Top-level ``Key: Value`` fields only; skip lines indented under nested blocks."""
    fields: dict[str, str] = {}
    for line in text.splitlines():
        if not line or line.startswith(" ") or line.startswith("\t"):
            continue
        key, separator, value = line.partition(":")
        if not separator:
            continue
        fields[key.strip()] = value.strip()
    return fields


def parse_json_object_output(text: str) -> dict[str, Any] | None:
    start = text.find("{")
    end = text.rfind("}")
    if start == -1 or end == -1 or end < start:
        return None

    try:
        payload = json.loads(text[start : end + 1])
    except json.JSONDecodeError:
        return None
    if not isinstance(payload, dict):
        return None
    return payload


def deployment_shape_base(deployment_shape: str) -> str:
    marker = "/versions/"
    if marker not in deployment_shape:
        return ""
    return deployment_shape.split(marker, maxsplit=1)[0]


def deployment_shape_account(deployment_shape_base_name: str) -> str:
    parts = deployment_shape_base_name.split("/")
    if len(parts) >= 4 and parts[0] == "accounts" and parts[2] == "deploymentShapes":
        return parts[1]
    return ""


def firectl_deployment_lookup_for_profile(
    account_id: str,
    deployment_id: str,
    firectl_binary: str,
    timeout_seconds: int,
    profile: str,
) -> FirectlLookupResult:
    args = [firectl_binary]
    if profile:
        args.extend(["-p", profile])
    args.extend(["-o", "json", "-a", account_id, "deployment", "get", deployment_id])

    result = run_command(args=args, timeout_seconds=timeout_seconds)
    if result is None:
        return FirectlLookupResult(
            status=FIRECTL_STATUS_LOOKUP_ERROR,
            created_by="",
            profile=profile,
            deployment_shape="",
            enable_hot_load=False,
        )

    stdout = result.stdout or ""
    stderr = result.stderr or ""

    # firectl-admin can exit non-zero on multi-region / DELETING deployments
    # while still streaming valid fields first; trust stdout when it has a deployment.
    json_fields = parse_json_object_output(stdout)
    if json_fields is not None and json_fields.get("name"):
        return FirectlLookupResult(
            status=str(json_fields.get("state", "")).strip() or FIRECTL_STATUS_LOOKUP_ERROR,
            created_by=str(json_fields.get("created_by", "")).strip(),
            profile=profile,
            deployment_shape=str(json_fields.get("deployment_shape", "")).strip(),
            enable_hot_load=parse_bool(json_fields.get("enable_hot_load")),
        )

    fields = parse_firectl_text_output(stdout)
    if fields.get("Name"):
        return FirectlLookupResult(
            status=fields.get("State", "").strip() or FIRECTL_STATUS_LOOKUP_ERROR,
            created_by=fields.get("Created By", "").strip(),
            profile=profile,
            deployment_shape=fields.get("Deployment Shape", "").strip(),
            enable_hot_load=parse_bool(fields.get("Enable Hot Load")),
        )

    combined = stderr + stdout
    if "NotFound" in combined or "not found" in combined.lower():
        return FirectlLookupResult(
            status=FIRECTL_STATUS_MISSING,
            created_by="",
            profile=profile,
            deployment_shape="",
            enable_hot_load=False,
        )

    return FirectlLookupResult(
        status=FIRECTL_STATUS_LOOKUP_ERROR,
        created_by="",
        profile=profile,
        deployment_shape="",
        enable_hot_load=False,
    )


def firectl_deployment_lookup(
    account_id: str,
    deployment_id: str,
    firectl_binary: str,
    timeout_seconds: int,
    profiles: list[str],
) -> FirectlLookupResult:
    if not account_id or not deployment_id:
        return FirectlLookupResult(
            status=FIRECTL_STATUS_NO_LABELS,
            created_by="",
            profile="",
            deployment_shape="",
            enable_hot_load=False,
        )

    candidate_profiles = profiles or [""]
    last_result: FirectlLookupResult | None = None
    for profile in candidate_profiles:
        result = firectl_deployment_lookup_for_profile(
            account_id=account_id,
            deployment_id=deployment_id,
            firectl_binary=firectl_binary,
            timeout_seconds=timeout_seconds,
            profile=profile,
        )
        last_result = result
        if result.status != FIRECTL_STATUS_MISSING:
            return result
    assert last_result is not None
    return last_result


