    def _is_tool_call_message(self, msg) -> bool:
        return (
            hasattr(msg, "recipient")
            and msg.recipient
            # Some models may hallucinate a 'final' channel while also emitting a recipient.
            # Such cases should be treated as normal content (not a tool call), so we exclude 'final'.
            and getattr(msg, "channel", None) != "final"
            and msg.recipient != "all"  # != all is needed, any specific recipient could be a tool
        )

    def _extract_message_text(self, msg) -> str:
        """Shared helper to extract text content from a harmony message.

        This reduces duplication between streaming and non-streaming parsing logic.
        """
        message_text = ""
        if hasattr(msg, "content") and msg.content:
            for content_item in msg.content:
                if hasattr(content_item, "text"):
                    message_text += content_item.text
                # else: content_item doesn't have text attribute, skip it
        return message_text

    def _extract_content_from_messages(self, messages) -> tuple:
        """Extract content and reasoning_content from harmony messages.

        Uses shared helper methods to reduce duplication between streaming and non-streaming parsing.
        Returns (content, reasoning_content) tuple.
        """
        final_content = ""
        analysis_content = ""

        for msg in messages:
            if (
                hasattr(msg, "author")
                and hasattr(msg.author, "role")
                and str(msg.author.role) == "Role.ASSISTANT"
                and hasattr(msg, "channel")
                and msg.content
            ):
                message_text = self._extract_message_text(msg)

                if msg.channel == "final":
                    final_content += message_text
                elif msg.channel == "analysis":
                    if not self._is_tool_call_message(msg) and message_text.strip():
                        analysis_content += message_text
                elif msg.channel == "commentary":
                    # Commentary channel can contain both tool calls and preambles.
                    # Only extract text content if this is NOT a tool call (preamble case).
                    if not self._is_tool_call_message(msg) and message_text.strip():
                        # This is a preamble - user-facing content that should be shown
                        final_content += message_text
                    # else: this is a tool call in commentary channel, ignore for content extraction
                else:
                    # Unknown channel - this should be rare but handle gracefully
                    import warnings

                    warnings.warn(f"Unknown channel '{msg.channel}' encountered, ignoring content")
            else:
                # Message doesn't match expected structure - log but don't fail
                if hasattr(msg, "author") and hasattr(msg, "channel"):
                    import warnings

                    warnings.warn(
                        f"Message with role '{getattr(msg.author, 'role', 'unknown') if hasattr(msg, 'author') else 'no_author'}' and channel '{msg.channel}' doesn't match expected structure"
                    )

        content = final_content if final_content else None
        reasoning_content = analysis_content if analysis_content else None
        return content, reasoning_content

    def _format_non_streaming_choice(self, choice: firetext.Choice):
        """Format complete harmony response for non-streaming mode."""
        tool_calls: List[ChatCompletionMessageToolCall] = []
        content: Optional[str] = None
        reasoning_content: Optional[str] = None

        try:
            # Use batch parser instead of StreamableParser to avoid parsing bugs
            # Parser chokes on EOS token being present at the very end
            tokens = choice.token_ids[:]
            while tokens and tokens[-1] in self._eos_token_ids:
                tokens.pop()
            messages = self.ENCODING.parse_messages_from_completion_tokens(tokens, role=Role.ASSISTANT)
            content, reasoning_content = self._extract_content_from_messages(messages)
            harmony_tool_calls = []
            for msg in mess

ages:
                if self._is_tool_call_message(msg):
                    # This is a tool call - use shared helper for text extraction
                    tool_content = self._extract_message_text(msg)

                    try:
                        import json

                        json.loads(tool_content.strip())  # Validate JSON
                    except (json.JSONDecodeError, ValueError):
                        self._has_json_error = True  # Signal that we found invalid JSON

                    harmony_tool_calls.append(
                        {
                            "id": _generate_call_id(),
                            "type": "function",
                            "function": {"name": _extract_tool_name(msg.recipient), "arguments": tool_content},
                        }
                    )
                # else: message doesn't match tool call pattern, skip it

            for i, tool_call in enumerate(harmony_tool_calls):
                tool_calls.append(
                    ChatCompletionMessageToolCall(
                        index=i,
                        id=tool_call["id"],
                        type=tool_call["type"],
                        function=ChatCompletionMessageToolCallFunction(
                            name=tool_call["function"]["name"], arguments=tool_call["function"]["arguments"]
                        ),
                    )
                )

        except Exception as e:
            # Fallback: if Harmony parsing fails (e.g., malformed output from fine-tuned model),
            # return raw tokens as content instead of raising an error
            logging.warning(
                f"Failed to parse Harmony format, falling back to raw content. Error: {e}. "
                f"Raw choice: {repr(choice)}"
            )
            # Decode raw tokens as fallback content
            try:
                raw_content = self.ENCODING.decode_utf8(choice.token_ids)
            except Exception as decode_error:
                raise Exception(f"Failed to decode {len(choice.token_ids)} tokens: {decode_error}")
            content = raw_content
            reasoning_content = None
            tool_calls = []

        # Build message
        msg_kwargs = {"role": "assistant"}
        if content is not None:
            msg_kwargs["content"] = content
        # else: no content to add to message
        if reasoning_content is not None:
            msg_kwargs["reasoning_content"] = reasoning_content
        # else: no reasoning content to add or feature disabled
        if tool_calls:
            msg_kwargs["tool_calls"] = tool_calls
        # else: no tool calls to add to message

        msg = ChatMessage(**msg_kwargs)

        # Determine finish reason based on tool calls
        if tool_calls:
            finish_reason = "tool_calls"  # Use "tool_calls" even if JSON is invalid
        else:
            finish_reason = choice.finish_reason

        return ChatCompletionResponseChoice(
            index=choice.index,
            message=msg,
            finish_reason=finish_reason,
            logprobs=self._format_logprobs(choice.logprobs),
            raw_output=self._format_raw_output(),
            token_ids=choice.token_ids if self.return_token_ids else None,
        )

