class TcRatelimitVerifier:
    """Text Completion Ratelimit Verifier (Redis-backed, write-through)

    Still tracks usage in Redis for backward compatibility and comparison,
    but per-metric enforcement decisions come from the Unkey verifier when
    available.
    """

    DEFAULT_RATELIMITS = {
        "requests": 1,
        "tokens_generated": 200.0,
        "tokens_prompt": 1000.0,
        "tokens_cache_adjusted_prompt": 1000.0,
    }

    def __init__(self, config_handle: ConfigHandle):
        self._config_handle = config_handle
        self.ratelimit_verifier = None
        self.redis_host = os.environ.get("REDIS_HOST")
        if self.redis_host is None:
            logging.info("RatelimitVerifier not created because REDIS_HOST is not set")
            return
        self.redis_port = int(os.environ.get("REDIS_PORT", "6379"))

        self.ratelimit_verifier = RatelimitVerifier(self.redis_host, self.redis_port, get_deployment_name())
        try:
            self.ratelimit_verifier.connect()
        except ConnectionError as e:
            logging.error(f"TcRatelimitVerifier: {e}")

    def get_config(self) -> ServerlessSettings:
        return self._config_handle.get_current()

    def is_enabled(self) -> bool:
        if self.get_config().is_ratelimit_verifier_disabled():
            return False

        if self.ratelimit_verifier is None or self.redis_host is None:
            return False

        connected = self.ratelimit_verifier.is_connected()
        if not connected:
            server_metrics.ratelimit_verifier_error_total.inc(1)

        return connected

    def get_default_ratelimits(self, account: str) -> Dict[str, float]:
        """Get the default rate limits for an account, taking into account any hard limits."""
        config = self.get_config()
        default_ratelimits = self.DEFAULT_RATELIMITS.copy()

        for metric, default_limit in default_ratelimits.items():
            hard_limit = config.get_hard_limit_per_second(account, metric)
            if hard_limit is not None:
                default_ratelimits[metric] = min(default_limit, hard_limit)

        return default_ratelimits

    def _validate_hard_limit(
        self, account: str, ratelimit_responses: Dict[str, RatelimitResponse]
    ) -> Optional[tuple[str, str]]:
        config = self.get_config()
        for metric, response in ratelimit_responses.items():
            if response.accepted:
                continue
            if response.is_hard_limit:
                return metric, f"hard limit metric={metric}, used={response.used}, limit={response.limit}"

            hard_limit_per_second = config.get_hard_limit_per_second(account, metric)
            if hard_limit_per_second is None:
                continue
            eps = 0.1
            if response.used >= hard_limit_per_second * 60 - eps:
                return (
                    metric,
                    f"hard limit metric={metric}, used={response.used}, limit={hard_limit_per_second * 60}",
                )
        return None

