def _make_full_hf_state(
    text_config: NemotronHTextConfig,
) -> dict[str, torch.Tensor]:
    model = NemotronHCausalTextModel(text_config)
    model_state = model.base_state_dict()
    cfg = text_config.base
    hf_state: dict[str, torch.Tensor] = {}
    _add_base_hf_weights(hf_state, model_state)
    for layer_idx, layer_type in enumerate(cfg.layers_block_type or []):
        if layer_type == "mamba":
            _add_mamba_hf_layer(hf_state, model_state, layer_idx=layer_idx)
        elif layer_type == "attention":
            _add_attention_hf_layer(hf_state, model_state, cfg=cfg, layer_idx=layer_idx)
        elif layer_type == "moe":
            _add_individual_moe_hf_layer(hf_state, model_state, cfg=cfg, layer_idx=layer_idx)
        elif layer_type == "mlp":
            _add_mlp_hf_layer(hf_state, model_state, layer_idx=layer_idx)
        else:
            raise ValueError(f"Unsupported test layer type {layer_type!r}")
    return hf_state


